local embedded = {
    ["features/sui_menu_hide"] = "-- sui_menu_hide.lua — Simple UI\
--\
-- Hides chosen tabs, submenus and items of the File Manager and Reader menus.\
--\
-- Entries are matched by the `.id` KOReader's MenuSorter stamps onto every\
-- sorted entry. Hidden ids are kept per target (\"fm\" / \"reader\") in\
-- SUISettings; a step registered in the shared menu hooks\
-- (infra/sui_menu_hooks.lua) prunes the live tab table whenever it is built\
-- or opened. Before pruning, the full tree (ids and labels) is saved to a\
-- file per target so the editor can list the menu of a context that is not\
-- open right now.\
--\
-- The Quick Settings tab and every ancestor of it are never removed, and a\
-- prune never leaves the menu without tabs.\
\
local SUISettings = require(\"infra/sui_store\")\
local _           = require(\"infra/sui_i18n\").translate\
local N_          = require(\"infra/sui_i18n\").ngettext\
local MenuHooks   = require(\"infra/sui_menu_hooks\")\
\
local M = {}\
\
M.PROTECTED = { _sui_qs_panel = true, orbitui_settings = true }\
local _owners = setmetatable({}, { __mode = \"k\" })\
local _active = false\
\
local SETTING_PREFIX = \"simpleui_menu_hidden_\"\
\
-- ---------------------------------------------------------------------------\
-- Pure tree functions\
-- ---------------------------------------------------------------------------\
\
-- A node's children: its submenu table, or the node itself for a tab (whose\
-- entries live in its array part).\
local function childrenOf(node)\
    return node.sub_item_table or node\
end\
\
-- True when the node is protected or contains a protected entry.\
local function holdsProtected(node)\
    if node.id and M.PROTECTED[node.id] then return true end\
    for _i, child in ipairs(childrenOf(node)) do\
        if type(child) == \"table\" and holdsProtected(child) then return true end\
    end\
    return false\
end\
\
local function isRemovable(node, hidden)\
    return node.id ~= nil and hidden[node.id] == true and not holdsProtected(node)\
end\
\
-- Removes list[i] and notes in `log` where it came from.\
local function removeAt(list, i, log)\
    local node = table.remove(list, i)\
    if log then log[#log + 1] = { list = list, node = node, after = list[i] } end\
end\
\
local function pruneList(list, hidden, log)\
    for i = #list, 1, -1 do\
        local node = list[i]\
        if type(node) == \"table\" then\
            if isRemovable(node, hidden) then\
                removeAt(list, i, log)\
            else\
                pruneList(childrenOf(node), hidden, log)\
            end\
        end\
    end\
end\
\
--- Puts back, in reverse order, the entries a prune noted in `log`.\
function M.restore(log)\
    for i = #log, 1, -1 do\
        local entry = log[i]\
        local pos = #entry.list + 1\
        for j, node in ipairs(entry.list) do\
            if node == entry.after then pos = j; break end\
        end\
        table.insert(entry.list, pos, entry.node)\
        log[i] = nil\
    end\
end\
\
--- Removes the entries whose id is in `hidden` from the tab table, in place.\
--- Protected entries stay, and so do all tabs if none would be left. When\
--- `log` is given, every removal is noted in it for M.restore.\
function M.prune(tabs, hidden, log)\
    if not next(hidden) then return end\
    local remaining = 0\
    for _i, tab in ipairs(tabs) do\
        if not isRemovable(tab, hidden) then remaining = remaining + 1 end\
    end\
    for i = #tabs, 1, -1 do\
        local tab = tabs[i]\
        if remaining > 0 and isRemovable(tab, hidden) then\
            removeAt(tabs, i, log)\
        else\
            pruneList(childrenOf(tab), hidden, log)\
        end\
    end\
end\
\
-- Label of an entry and whether it came from a `text_func` (its value changes\
-- with the state of the menu).\
local function entryText(node)\
    if type(node.text) == \"string\" then return node.text, false end\
    if type(node.text_func) == \"function\" then\
        -- Do not evaluate/persist current values, book names or provider\
        -- callbacks just to snapshot a menu. Its stable id stays selectable.\
        return node.id, true\
    end\
end\
\
--- Returns the menu as plain data: an array of { id, text, dynamic?, children? }.\
--- Entries without an id are skipped; dynamic submenus are not expanded.\
function M.extractTree(tabs, tabLabel)\
    local function walk(list, is_tabs)\
        local out = {}\
        for _i, node in ipairs(list) do\
            if type(node) == \"table\" and type(node.id) == \"string\" then\
                local text, dynamic = is_tabs and tabLabel and tabLabel(node.id)\
                if not text then text, dynamic = entryText(node) end\
                local entry = { id = node.id, text = text or node.id, dynamic = dynamic or nil }\
                local children = walk(childrenOf(node), false)\
                if #children > 0 then entry.children = children end\
                out[#out + 1] = entry\
            end\
        end\
        return out\
    end\
    return walk(tabs, true)\
end\
\
-- ---------------------------------------------------------------------------\
-- Hidden ids\
-- ---------------------------------------------------------------------------\
\
local function settingKey(target) return SETTING_PREFIX .. target end\
\
--- Set of hidden ids ({ [id] = true }) of a target; never nil.\
function M.getHidden(target)\
    local stored = SUISettings:get(settingKey(target))\
    return type(stored) == \"table\" and stored or {}\
end\
\
-- The menu object of the running File Manager / Reader of a target, if any.\
local function liveMenu(target)\
    local class_path = target == MenuHooks.TARGET.FM\
        and \"apps/filemanager/filemanager\" or \"apps/reader/readerui\"\
    local class = package.loaded[class_path]\
    return class and class.instance and class.instance.menu\
end\
\
-- Re-applies the hidden set to the menu table of a running context, so the\
-- table is already current before the menu is next opened or looked up.\
local function applyLive(target)\
    local menu = liveMenu(target)\
    if menu and menu.tab_item_table ~= nil then MenuHooks.refresh(menu, target) end\
end\
\
--- Hides or shows one id of a target.\
function M.setHidden(target, id, hidden)\
    local set = {}\
    for k in pairs(M.getHidden(target)) do set[k] = true end\
    set[id] = hidden and true or nil\
    if next(set) then\
        SUISettings:set(settingKey(target), set)\
    else\
        SUISettings:del(settingKey(target))\
    end\
    applyLive(target)\
end\
\
--- Shows every hidden entry again, in both menus.\
function M.clearAll()\
    for _i, target in pairs(MenuHooks.TARGET) do\
        SUISettings:del(settingKey(target))\
        applyLive(target)\
    end\
end\
\
-- ---------------------------------------------------------------------------\
-- Menu tree snapshot\
-- ---------------------------------------------------------------------------\
\
local SAVE_DELAY = 2 -- seconds between a menu build and the snapshot write\
\
local _trees   = {} -- target -> tree captured in this session\
local _written = {} -- target -> signature of the tree last written to / read from disk\
local _pending = {} -- target -> tree waiting to be written\
\
local function treePath(target)\
    return require(\"datastorage\"):getSettingsDir() .. \"/simpleui/menu_tree_\" .. target .. \".lua\"\
end\
\
local function readTreeFile(target)\
    local ok, tree = pcall(function()\
        return require(\"luasettings\"):open(treePath(target)):readSetting(\"tree\")\
    end)\
    return ok and type(tree) == \"table\" and tree or nil\
end\
\
-- Identifies a tree by its ids and stable labels; labels that come from a\
-- `text_func` are left out, as their value changes without the menu changing.\
local function signature(tree)\
    local out = {}\
    local function walk(nodes)\
        for _i, entry in ipairs(nodes) do\
            out[#out + 1] = entry.id\
            if not entry.dynamic then out[#out + 1] = entry.text end\
            if entry.children then\
                out[#out + 1] = \"{\"\
                walk(entry.children)\
                out[#out + 1] = \"}\"\
            end\
        end\
    end\
    walk(tree)\
    return table.concat(out, \"\\0\")\
end\
\
local function flushTree(target)\
    local tree = _pending[target]\
    _pending[target] = nil\
    if not tree or not _active then return end\
    if _written[target] == nil then\
        local stored = readTreeFile(target)\
        _written[target] = stored and signature(stored) or false\
    end\
    local sig = signature(tree)\
    if sig == _written[target] then return end\
    local ok, err = pcall(function()\
        local file = require(\"luasettings\"):open(treePath(target))\
        file:saveSetting(\"tree\", tree)\
        file:flush()\
    end)\
    if ok then\
        _written[target] = sig\
    else\
        require(\"logger\").warn(\"simpleui/menu_hide: could not save menu tree:\", err)\
    end\
end\
\
-- Queues the snapshot for writing shortly after the menu has been built.\
local function saveTree(target, tree)\
    local queued = _pending[target] ~= nil\
    _pending[target] = tree\
    if not queued then require(\"ui/uimanager\"):scheduleIn(SAVE_DELAY, flushTree, target) end\
end\
\
--- Label of a native tab, from the slot that describes its icon.\
function M.tabLabel(id)\
    local ok, SUIStyle = pcall(require, \"features/sui_style\")\
    if not ok then return nil end\
    for _i, slot in ipairs(SUIStyle.SLOTS) do\
        if slot.tab_id == id and slot.label then return slot.label() end\
    end\
end\
\
-- Builds the menu table of a running File Manager / Reader that has not been\
-- opened yet, so its entries can be listed. The menu hook step captures the\
-- tree as the table is built. Does nothing once a table exists, which also\
-- keeps an open menu untouched.\
local function buildLiveMenus()\
    for _i, target in pairs(MenuHooks.TARGET) do\
        local menu = liveMenu(target)\
        if menu and menu.tab_item_table == nil and menu.setUpdateItemTable then\
            local ok, err = pcall(menu.setUpdateItemTable, menu)\
            if not ok then\
                require(\"logger\").warn(\"simpleui/menu_hide: could not build the menu:\", err)\
            end\
        end\
    end\
end\
\
--- Menu tree of a target: the one captured in this session, else the saved copy.\
function M.loadTree(target)\
    if not _trees[target] then _trees[target] = readTreeFile(target) end\
    return _trees[target]\
end\
\
-- ---------------------------------------------------------------------------\
-- Menu hook step\
-- ---------------------------------------------------------------------------\
\
local SEEN = \"_sui_menu_hide_seen\"\
local LOG  = \"_sui_menu_hide_log\"\
\
local function prepare(menu, target)\
    if not _active then return end\
    local tabs = menu.tab_item_table\
    if type(tabs) ~= \"table\" then return end\
    -- The table is cached between openings; capture it once per build, before\
    -- anything is removed.\
    if not tabs[SEEN] then\
        local tree = M.extractTree(tabs, M.tabLabel)\
        _trees[target] = tree\
        saveTree(target, tree)\
        tabs[SEEN] = true\
        tabs[LOG] = {}\
    end\
    -- The table is cached and KOReader cannot rebuild it, so the previous\
    -- prune is undone before pruning with the current hidden set.\
    M.restore(tabs[LOG])\
    M.prune(tabs, M.getHidden(target), tabs[LOG])\
end\
\
--- A top-level tab that the current prune took out of `tabs`, by id; nil if\
--- the tab is shown or does not exist. Lets other features keep using a tab\
--- the user has hidden from the menu.\
function M.findHiddenTab(tabs, id)\
    for _i, entry in ipairs(tabs[LOG] or {}) do\
        if entry.list == tabs and entry.node.id == id then return entry.node end\
    end\
end\
\
-- The tab the menu opens on is remembered by position. When the tab layout\
-- changes (a tab hidden or shown), that position is moved to the same tab.\
local LAYOUT = \"_sui_menu_hide_layout\"\
\
local function savedTabIndex(menu, target)\
    if target == MenuHooks.TARGET.FM then\
        return G_reader_settings:readSetting(\"filemanagermenu_tab_index\")\
    end\
    return menu.last_tab_index\
end\
\
local function saveTabIndex(menu, target, index)\
    if target == MenuHooks.TARGET.FM then\
        G_reader_settings:saveSetting(\"filemanagermenu_tab_index\", index)\
    else\
        menu.last_tab_index = index\
    end\
end\
\
local function keepLastTab(menu, target)\
    local tabs = menu.tab_item_table\
    if type(tabs) ~= \"table\" then return end\
    local after = {}\
    for i, tab in ipairs(tabs) do after[i] = tab.id or false end\
    local before = tabs[LAYOUT]\
    tabs[LAYOUT] = after\
    local index = savedTabIndex(menu, target)\
    local id = before and index and before[index]\
    if not id then return end\
    local new_index = 1\
    for i, tab_id in ipairs(after) do\
        if tab_id == id then new_index = i; break end\
    end\
    if new_index ~= index then saveTabIndex(menu, target, new_index) end\
end\
\
function M.install(owner)\
    _owners[owner or M] = true\
    _active = true\
    MenuHooks.register{\
        id      = \"menu_hide\",\
        order   = MenuHooks.ORDER.MENU_HIDE,\
        prepare = prepare,\
    }\
    MenuHooks.register{\
        id      = \"menu_hide_last_tab\",\
        order   = MenuHooks.ORDER.TAB_LAYOUT,\
        prepare = keepLastTab,\
    }\
end\
\
-- ---------------------------------------------------------------------------\
-- Editor (Style > Hide Menu Items)\
-- ---------------------------------------------------------------------------\
\
-- Restore live menus and cancel queued snapshots on last-owner teardown.\
function M.uninstall(owner)\
    _owners[owner or M] = nil\
    if next(_owners) then return end\
    _active = false\
    require(\"ui/uimanager\"):unschedule(flushTree)\
    _pending, _trees, _written = {}, {}, {}\
    for _, target in pairs(MenuHooks.TARGET) do\
        local menu = liveMenu(target)\
        local tabs = menu and menu.tab_item_table\
        if tabs then\
            M.restore(tabs[LOG] or {})\
            tabs[SEEN], tabs[LOG], tabs[LAYOUT] = nil, nil, nil\
        end\
    end\
end\
\
local function showProtectedNotice()\
    local InfoMessage = require(\"ui/widget/infomessage\")\
    require(\"ui/uimanager\"):show(InfoMessage:new{\
        text    = _(\"This item can't be hidden\"),\
        timeout = 3,\
    })\
end\
\
-- Checkbox row that shows or hides `node`. A protected node is always shown.\
local function makeToggleRow(target, node, text, protected)\
    return {\
        text           = text,\
        keep_menu_open = true,\
        checked_func   = function()\
            return protected or not M.getHidden(target)[node.id]\
        end,\
        callback       = function()\
            if protected then return showProtectedNotice() end\
            M.setHidden(target, node.id, not M.getHidden(target)[node.id])\
        end,\
    }\
end\
\
local function treeHoldsProtected(node)\
    if M.PROTECTED[node.id] then return true end\
    for _i, child in ipairs(node.children or {}) do\
        if treeHoldsProtected(child) then return true end\
    end\
    return false\
end\
\
-- Number of hidden entries in `nodes`; the entries inside a hidden submenu are\
-- not counted on top of it, and ids that are not in the menu are ignored.\
local function countHidden(nodes, hidden)\
    local n = 0\
    for _i, node in ipairs(nodes) do\
        if hidden[node.id] == true and not treeHoldsProtected(node) then\
            n = n + 1\
        elseif node.children then\
            n = n + countHidden(node.children, hidden)\
        end\
    end\
    return n\
end\
\
local function hiddenLabel(n)\
    if n == 0 then return \"\" end\
    return string.format(N_(\"%d hidden\", \"%d hidden\", n), n)\
end\
\
-- Greys out `row` and makes it inert while `locked()` is true. The settings\
-- window drops rows with `enabled_func` false, so it gets `dim` instead.\
local function applyLock(row, locked, is_sui)\
    if is_sui then\
        row.dim = locked() or nil\
    else\
        row.enabled_func = function() return not locked() end\
    end\
    return row\
end\
\
-- Rows for `nodes`; `locked()` tells whether an ancestor submenu is hidden.\
local function makeTreeRows(target, nodes, locked, is_sui)\
    local rows = {}\
    for _i, node in ipairs(nodes) do\
        local protected = treeHoldsProtected(node)\
        if node.children then\
            local show = applyLock(makeToggleRow(target, node, _(\"Show this menu\"), protected), locked, is_sui)\
            show.separator = true\
            local function children_locked()\
                return locked() or M.getHidden(target)[node.id] == true\
            end\
            local function state()\
                local hidden = M.getHidden(target)\
                if hidden[node.id] == true and not protected then return _(\"Hidden\") end\
                return hiddenLabel(countHidden(node.children, hidden))\
            end\
            rows[#rows + 1] = applyLock({\
                text                = node.text,\
                value_func          = state,\
                mandatory_func      = state,\
                sub_item_table_func = function()\
                    local sub = { show }\
                    for _j, row in ipairs(makeTreeRows(target, node.children, children_locked, is_sui)) do\
                        sub[#sub + 1] = row\
                    end\
                    return sub\
                end,\
            }, locked, is_sui)\
        else\
            rows[#rows + 1] = applyLock(makeToggleRow(target, node, node.text, protected), locked, is_sui)\
        end\
    end\
    return rows\
end\
\
local function notLocked() return false end\
\
local function makeContextRow(target, label, missing, is_sui)\
    local function hiddenCount()\
        local hidden = M.getHidden(target)\
        local tree = M.loadTree(target)\
        local n = 0\
        if tree then\
            n = countHidden(tree, hidden)\
        else\
            for _id in pairs(hidden) do n = n + 1 end\
        end\
        return hiddenLabel(n)\
    end\
    return {\
        text           = label,\
        value_func     = hiddenCount,\
        mandatory_func = hiddenCount,\
        sub_item_table_func = function()\
            local tree = M.loadTree(target)\
            if not tree then\
                return { { text = missing, callback = function() end } }\
            end\
            return makeTreeRows(target, tree, notLocked, is_sui)\
        end,\
    }\
end\
\
-- Settings-window row for the note: a grey rounded card with the warning\
-- glyph centred in its own column, a thin rule, then the text in a small\
-- regular face, wrapped over as many lines as it needs. The text composites\
-- over the card instead of painting its own white background.\
local function makeNoteWidget(ctx, text)\
    local SUIStyle        = require(\"features/sui_style\")\
    local UI              = require(\"infra/sui_core\")\
    local Screen          = require(\"device\").screen\
    local Geom            = require(\"ui/geometry\")\
    local Size            = require(\"ui/size\")\
    local RoundedFrame    = require(\"infra/sui_backdrop\").RoundedFrame\
    local CenterContainer = require(\"ui/widget/container/centercontainer\")\
    local HorizontalGroup = require(\"ui/widget/horizontalgroup\")\
    local HorizontalSpan  = require(\"ui/widget/horizontalspan\")\
    local LineWidget      = require(\"ui/widget/linewidget\")\
    local VerticalGroup   = require(\"ui/widget/verticalgroup\")\
    local VerticalSpan    = require(\"ui/widget/verticalspan\")\
    local SZ              = ctx.SZ\
    local function dp(n) return SZ(Screen:scaleBySize(n)) end\
\
    local h_pad, v_pad, margin = dp(8), dp(12), dp(12)\
    local icon_col, gap, rule_w = dp(56), dp(14), Size.line.thin\
\
    local icon = UI.makeColoredText{\
        text    = SUIStyle.ICON.warning,\
        face    = SUIStyle.glyphFace(dp(22)),\
        fgcolor = SUIStyle.COLOR.text_primary,\
        padding = 0,\
    }\
    local body = UI.makeAlphaTextBox{\
        text    = text,\
        face    = require(\"ui/font\"):getFace(SUIStyle.FACE_REGULAR, SZ(SUIStyle.FS_DETAIL)),\
        fgcolor = SUIStyle.COLOR.text_primary,\
        width   = math.max(1, ctx.inner_w - 2 * h_pad - icon_col - rule_w - gap),\
    }\
    local text_h = body:getSize().h\
\
    local row = HorizontalGroup:new{\
        align = \"center\",\
        CenterContainer:new{ dimen = Geom:new{ w = icon_col, h = text_h }, icon },\
        LineWidget:new{\
            dimen      = Geom:new{ w = rule_w, h = text_h },\
            background = SUIStyle.accent(SUIStyle.COLOR.gray_strong),\
        },\
        HorizontalSpan:new{ width = gap },\
        body,\
    }\
    local card = RoundedFrame:new{\
        radius     = dp(12),\
        bordersize = 0,\
        background = SUIStyle.COLOR.surface_flat,\
        padding    = 0,\
        CenterContainer:new{\
            dimen = Geom:new{ w = ctx.inner_w, h = text_h + 2 * v_pad },\
            row,\
        },\
    }\
    return VerticalGroup:new{\
        align = \"left\",\
        VerticalSpan:new{ width = margin },\
        card,\
        VerticalSpan:new{ width = margin },\
    }\
end\
\
--- Menu items of Style > Hide Menu Items. `ctx_menu` is the caller's menu\
--- context; inside the settings window it has `is_sui` set.\
function M.makeMenuItems(ctx_menu)\
    local is_sui = ctx_menu and ctx_menu.is_sui or false\
    buildLiveMenus()\
    local fm_row = makeContextRow(MenuHooks.TARGET.FM, _(\"File Manager\"),\
        _(\"Open the File Manager once to list its menu\"), is_sui)\
    local reader_row = makeContextRow(MenuHooks.TARGET.READER, _(\"Reader\"),\
        _(\"Open a book once to list the Reader menu\"), is_sui)\
    reader_row.separator = true\
    local note = _(\"Make sure you can still open Simple UI settings, e.g. with a quick action.\")\
    return {\
        fm_row,\
        reader_row,\
        {\
            text     = _(\"Show All Items\"),\
            callback = function(touch_menu)\
                local ConfirmBox = require(\"ui/widget/confirmbox\")\
                require(\"ui/uimanager\"):show(ConfirmBox:new{\
                    text        = _(\"Show all hidden menu items again?\"),\
                    ok_callback = function()\
                        M.clearAll()\
                        -- The counts shown on the rows are stale once the box closes.\
                        if is_sui then\
                            if ctx_menu.refresh then ctx_menu.refresh() end\
                        elseif touch_menu and touch_menu.updateItems then\
                            touch_menu:updateItems()\
                        end\
                    end,\
                })\
            end,\
            separator = true,\
        },\
        {\
            text           = note,\
            keep_menu_open = true,\
            callback       = function() end,\
            sui_build      = is_sui and function(ctx) return makeNoteWidget(ctx, note) end or nil,\
        },\
    }\
end\
\
return M\
",
    ["features/sui_patch_compat"] = "-- sui_patch_compat.lua — Simple UI\
-- Finds user patches known to clash with Simple UI and offers to disable them.\
--\
-- A disabled patch is renamed to <name>.disabled, the same way the native patch\
-- management menu does it, so it can be enabled again from there. A patch that\
-- the user keeps is remembered and not offered again. A patch that came back\
-- under its own name after Simple UI disabled it was enabled on purpose, so it\
-- is kept as well.\
--\
-- Patches run before the plugins start, so a change only takes effect after a\
-- restart; the dialog ends with one.\
--\
-- Public API\
--   PatchCompat.check() -> bool    true when the dialog is shown, i.e. startup\
--                                  must stop\
--   PatchCompat.detect(dir, allowed, disabled) -> found, reenabled\
--   PatchCompat.apply(dir, found, selected)\
\
local _           = require(\"infra/sui_i18n\").translate\
local SUISettings = require(\"infra/sui_store\")\
\
local PatchCompat = {}\
\
local ALLOWED_KEY  = \"simpleui_patch_compat_allowed\"\
local DISABLED_KEY = \"simpleui_patch_compat_disabled\"\
\
-- A patch whose source contains this name already supports Simple UI.\
local ADAPTED_MARKER = \"_simpleui_native_build\"\
\
-- Patches that clash with Simple UI, grouped by the reason. Built on demand so\
-- the reasons are translated when they are shown.\
local function catalog()\
    return {\
        {\
            reason = _(\"Replaces the navigation bar or the quick settings\"),\
            files  = { \"2-navbar-vos.lua\", \"2-custom-navbar.lua\", \"2-quick-settings.lua\" },\
        },\
        {\
            reason = _(\"Replaces the title bar\"),\
            files  = {\
                \"2-filemanager-titlebar.lua\", \"2-filemanager-title-bar.lua\", \"2-custom-titlebar.lua\",\
                \"2-filemanager-metadata-tabs.lua\",\
            },\
        },\
        {\
            reason = _(\"Changes the size of the menus or the fonts\"),\
            files  = { \"2-menu-size.lua\", \"2--ui-font.lua\", \"2-ui-font.lua\" },\
        },\
        {\
            reason = _(\"Duplicates the author and series browser\"),\
            files  = { \"2-author-series.lua\", \"2-browser-up-folder.lua\" },\
        },\
        {\
            reason = _(\"Draws on the book covers without supporting Simple UI\"),\
            files  = {\
                \"2-pages-badge_estimate.lua\", \"2-finished-badge.lua\", \"2-reading-percentage.lua\",\
                \"2-real-books.lua\", \"2-percent-badge.lua\",\
            },\
        },\
        {\
            reason = _(\"Hides Wi-Fi dialogs, and any other dialog that mentions Wi-Fi\"),\
            files  = { \"2-disable-wifi-notifications.lua\", \"2-non-blocking-wifi.lua\" },\
        },\
        {\
            reason = _(\"Changes how books are opened from the file browser\"),\
            files  = { \"2-browser-double-tap.lua\" },\
        },\
    }\
end\
\
local function readAll(path)\
    local f = io.open(path, \"rb\")\
    if not f then return nil end\
    local source = f:read(\"*a\")\
    f:close()\
    return source or \"\"\
end\
\
local function exists(path)\
    local f = io.open(path, \"rb\")\
    if not f then return false end\
    f:close()\
    return true\
end\
\
-- Patches of the catalog present in `dir` and not allowed, as\
-- { { file, reason }, ... }. `reenabled` lists the ones Simple UI had disabled\
-- and that are active again. A patch with a .disabled copy beside it is left alone.\
function PatchCompat.detect(dir, allowed, disabled)\
    local found, reenabled = {}, {}\
    for _i, group in ipairs(catalog()) do\
        for _j, file in ipairs(group.files) do\
            local source = readAll(dir .. \"/\" .. file)\
            if source and not allowed[file]\
                    and not source:find(ADAPTED_MARKER, 1, true)\
                    and not exists(dir .. \"/\" .. file .. \".disabled\") then\
                if disabled[file] then\
                    reenabled[#reenabled + 1] = file\
                else\
                    found[#found + 1] = { file = file, reason = group.reason }\
                end\
            end\
        end\
    end\
    return found, reenabled\
end\
\
-- The settings directory is created later in startup, so a write made before\
-- that would be lost.\
local function ensureSettingsDir()\
    local ok_ds, DataStorage = pcall(require, \"datastorage\")\
    local ok_lfs, lfs = pcall(require, \"libs/libkoreader-lfs\")\
    if not (ok_ds and ok_lfs) then return end\
    local dir = DataStorage:getSettingsDir() .. \"/simpleui\"\
    if lfs.attributes(dir, \"mode\") ~= \"directory\" then lfs.mkdir(dir) end\
end\
\
local function allow(files)\
    ensureSettingsDir()\
    local allowed = SUISettings:get(ALLOWED_KEY) or {}\
    for _i, file in ipairs(files) do allowed[file] = true end\
    SUISettings:set(ALLOWED_KEY, allowed)\
end\
\
-- Disables the patches of `found` flagged in `selected`; the others are allowed.\
function PatchCompat.apply(dir, found, selected)\
    local disabled = SUISettings:get(DISABLED_KEY) or {}\
    local kept, renamed = {}, false\
    for _i, item in ipairs(found) do\
        local path = dir .. \"/\" .. item.file\
        if selected[item.file] and os.rename(path, path .. \".disabled\") then\
            disabled[item.file] = true\
            renamed = true\
        elseif not selected[item.file] then\
            kept[#kept + 1] = item.file\
        end\
    end\
    if renamed then\
        ensureSettingsDir()\
        SUISettings:set(DISABLED_KEY, disabled)\
    end\
    if #kept > 0 then allow(kept) end\
end\
\
local function restart()\
    local Event = require(\"ui/event\")\
    require(\"ui/uimanager\"):broadcastEvent(Event:new(\"Restart\"))\
end\
\
local function message()\
    return _(\"These patches clash with Simple UI and can cause crashes or a broken layout. The checked ones will be disabled. Uncheck a patch to keep it, at your own risk. A disabled patch can be enabled again in Patch management.\")\
end\
\
-- Plain question, used when the sheet cannot be built.\
local function showFallback(dir, found)\
    local ConfirmBox = require(\"ui/widget/confirmbox\")\
    local names, all = {}, {}\
    for _i, item in ipairs(found) do\
        names[#names + 1] = item.file\
        all[item.file] = true\
    end\
    require(\"ui/uimanager\"):show(ConfirmBox:new{\
        text        = message() .. \"\\n\\n\" .. table.concat(names, \"\\n\"),\
        dismissable = false,\
        ok_text     = _(\"Disable and restart\"),\
        cancel_text = _(\"Keep and restart\"),\
        ok_callback = function()\
            PatchCompat.apply(dir, found, all)\
            restart()\
        end,\
        cancel_callback = function()\
            PatchCompat.apply(dir, found, {})\
            restart()\
        end,\
    })\
end\
\
local function showSheet(dir, found)\
    local ActionSheet = require(\"engines/sui_action_sheet\")\
    local selected = {}\
    for _i, item in ipairs(found) do selected[item.file] = true end\
\
    local window\
    local function sections()\
        local list, rows, last_reason = {}, nil, nil\
        for _i, item in ipairs(found) do\
            if item.reason ~= last_reason then\
                last_reason = item.reason\
                rows = {}\
                list[#list + 1] = { type = \"note\", text = item.reason }\
                list[#list + 1] = { type = \"rows\", rows = rows }\
            end\
            local file = item.file\
            rows[#rows + 1] = { {\
                text     = file:gsub(\"%.lua$\", \"\"),\
                toggle   = selected[file] == true,\
                callback = function()\
                    selected[file] = not selected[file] or nil\
                    window:update{ sections = sections() }\
                end,\
            } }\
        end\
        list[#list + 1] = { type = \"segments\", items = { {\
            text     = _(\"Apply and restart\"),\
            primary  = true,\
            callback = function()\
                window:close()\
                PatchCompat.apply(dir, found, selected)\
                restart()\
            end,\
        } } }\
        return list\
    end\
\
    window = ActionSheet.show{\
        name        = \"sui_win_patch_compat\",\
        title       = _(\"Incompatible patches\"),\
        message     = message(),\
        dismissable = false,\
        sections    = sections(),\
    }\
end\
\
local function show(dir, found)\
    require(\"ui/uimanager\"):scheduleIn(0.5, function()\
        if not pcall(showSheet, dir, found) then showFallback(dir, found) end\
    end)\
end\
\
function PatchCompat.check()\
    local ok_ds, DataStorage = pcall(require, \"datastorage\")\
    if not ok_ds then return false end\
    local ok_up, userpatch = pcall(require, \"userpatch\")\
    if ok_up and userpatch.arePatchesDisabled and userpatch.arePatchesDisabled() then\
        return false\
    end\
\
    local dir = DataStorage:getPatchesDir()\
    local found, reenabled = PatchCompat.detect(dir,\
        SUISettings:get(ALLOWED_KEY) or {}, SUISettings:get(DISABLED_KEY) or {})\
    if #reenabled > 0 then allow(reenabled) end\
    if #found == 0 then return false end\
\
    show(dir, found)\
    return true\
end\
\
return PatchCompat\
",
    ["infra/sui_migrations"] = "-- sui_migrations.lua — Simple UI\
-- One-time settings and user-data migrations, run at plugin init. Each step is\
-- guarded by its own flag and runs inside pcall, so a failure never blocks the\
-- plugin from loading. main.lua requires this module only while the first or last\
-- flag is missing; an already migrated install never loads it.\
\
local logger      = require(\"logger\")\
local SUISettings = require(\"infra/sui_store\")\
\
local M = {}\
\
function M.run()\
    -- -------------------------------------------------------------------\
    -- User-data migration (runs once per install / once after upgrade).\
    --\
    -- v1: move user files out of the plugin folder into DataStorage so\
    --     they survive plugin updates, and normalise all settings keys to\
    --     the simpleui_ / navbar_ namespace.\
    -- -------------------------------------------------------------------\
    if not G_reader_settings:isTrue(\"simpleui_userdata_migrated_v1\") then\
        pcall(function()\
            local ok_ds, DataStorage = pcall(require, \"datastorage\")\
            local ok_lfs, lfs        = pcall(require, \"libs/libkoreader-lfs\")\
            local ok_ffi, ffiutil    = pcall(require, \"ffi/util\")\
            if not (ok_ds and ok_lfs and ok_ffi) then return end\
\
            local data_dir = DataStorage:getSettingsDir() .. \"/simpleui\"\
\
            -- ── 1. Migrate user files (copy, never overwrite) ─────────\
            -- Directory structure is guaranteed by the startup block in main.lua.\
            -- Resolve plugin root from this file's path (one level below it).\
            local src_info   = debug.getinfo(1, \"S\").source or \"\"\
            local plugin_root = src_info:sub(1,1) == \"@\"\
                and src_info:sub(2):match(\"^(.*)/infra/[^/]+$\") or nil\
            if plugin_root and plugin_root:sub(1,1) ~= \"/\" then\
                local ok_lfs2, lfs2 = pcall(require, \"libs/libkoreader-lfs\")\
                local cwd = ok_lfs2 and lfs2 and lfs2.currentdir()\
                if cwd then plugin_root = cwd .. \"/\" .. plugin_root end\
            end\
\
            if plugin_root then\
                -- Copy files from src/ to dst/ (never overwrite existing).\
                local function copyDirContents(from_dir, to_dir)\
                    if lfs.attributes(from_dir, \"mode\") ~= \"directory\" then return end\
                    for fname in lfs.dir(from_dir) do\
                        if fname ~= \".\" and fname ~= \"..\" then\
                            local src_f = from_dir .. \"/\" .. fname\
                            local dst_f = to_dir .. \"/\" .. fname\
                            if lfs.attributes(src_f, \"mode\") == \"file\"\
                                and lfs.attributes(dst_f, \"mode\") ~= \"file\" then\
                                ffiutil.copyFile(src_f, dst_f)\
                            end\
                        end\
                    end\
                end\
\
                -- Removes all plain files inside dir, then the dir itself.\
                -- Skips silently if dir doesn't exist or still has subdirs.\
                local function removeDirIfEmpty(dir)\
                    if lfs.attributes(dir, \"mode\") ~= \"directory\" then return end\
                    for fname in lfs.dir(dir) do\
                        if fname ~= \".\" and fname ~= \"..\" then\
                            local p = dir .. \"/\" .. fname\
                            if lfs.attributes(p, \"mode\") == \"file\" then\
                                os.remove(p)\
                            end\
                        end\
                    end\
                    lfs.rmdir(dir)  -- only succeeds when empty\
                end\
\
                -- icons/custom → DataStorage/simpleui/sui_icons/\
                -- then remove the now-redundant in-plugin directory.\
                copyDirContents(plugin_root .. \"/icons/custom\",\
                                data_dir    .. \"/sui_icons\")\
                removeDirIfEmpty(plugin_root .. \"/icons/custom\")\
\
                -- modules/custom_quotes → DataStorage/simpleui/sui_quotes/\
                -- then remove the now-redundant in-plugin directory.\
                copyDirContents(plugin_root .. \"/modules/custom_quotes\",\
                                data_dir    .. \"/sui_quotes\")\
                removeDirIfEmpty(plugin_root .. \"/modules/custom_quotes\")\
            end\
\
            -- ── 2. Migrate renamed settings keys ──────────────────────\
            -- Each entry: { old_key, new_key }\
            local key_renames = {\
                { \"sui_tbr_list\",             \"simpleui_tbr_list\"                    },\
                { \"quote_deck_order\",          \"simpleui_quote_deck_order\"            },\
                { \"quote_deck_pos\",            \"simpleui_quote_deck_pos\"              },\
                { \"quote_deck_count\",          \"simpleui_quote_deck_count\"            },\
                { \"quote_hl_deck_order\",       \"simpleui_quote_hl_deck_order\"         },\
                { \"quote_hl_deck_pos\",         \"simpleui_quote_hl_deck_pos\"           },\
                { \"quote_hl_deck_count\",       \"simpleui_quote_hl_deck_count\"         },\
                { \"quote_custom_deck_order\",   \"simpleui_quote_custom_deck_order\"     },\
                { \"quote_custom_deck_pos\",     \"simpleui_quote_custom_deck_pos\"       },\
                { \"quote_custom_deck_count\",   \"simpleui_quote_custom_deck_count\"     },\
                { \"quote_custom_deck_file\",    \"simpleui_quote_custom_deck_file\"      },\
                -- quote_source and quote_custom_file are per-instance (prefixed\
                -- with navbar_homescreen_ at runtime); migrate all known slots.\
                { \"navbar_homescreen_quote_source\",      \"navbar_homescreen_simpleui_quote_source\"      },\
                { \"navbar_homescreen_quote_custom_file\", \"navbar_homescreen_simpleui_quote_custom_file\" },\
            }\
            for _, pair in ipairs(key_renames) do\
                local old_key, new_key = pair[1], pair[2]\
                local val = G_reader_settings:readSetting(old_key)\
                if val ~= nil and G_reader_settings:readSetting(new_key) == nil then\
                    G_reader_settings:saveSetting(new_key, val)\
                end\
                G_reader_settings:delSetting(old_key)\
            end\
\
            logger.info(\"simpleui: userdata migration v1 complete\")\
        end)\
        G_reader_settings:saveSetting(\"simpleui_userdata_migrated_v1\", true)\
    end\
    -- -------------------------------------------------------------------\
    -- Settings migration v2: move all navbar_* and simpleui_* keys from\
    -- G_reader_settings into SUISettings (the dedicated per-plugin store).\
    --\
    -- This runs once on first boot after the Phase-3 refactor.  It is safe\
    -- to re-run if interrupted: keys that already exist in SUISettings are\
    -- not overwritten; keys successfully copied are removed from\
    -- G_reader_settings.\
    -- -------------------------------------------------------------------\
    if not SUISettings:isTrue(\"simpleui_settings_migrated_v2\") then\
        pcall(function()\
            -- Enumerate every key currently stored in G_reader_settings\
            -- and migrate the ones owned by SimpleUI.\
            local raw = G_reader_settings.data  -- LuaSettings exposes .data\
            if type(raw) ~= \"table\" then return end\
\
            -- Collect owned keys first; deleting from raw while iterating\
            -- it with pairs() has undefined behaviour in Lua and can cause\
            -- entries to be skipped.\
            local to_migrate = {}\
            for k, v in pairs(raw) do\
                local owned = (type(k) == \"string\")\
                    and (k:sub(1, 7) == \"navbar_\" or k:sub(1, 9) == \"simpleui_\")\
                    -- Keep the v1 and v2 migration flags in G_reader_settings\
                    -- so they survive a factory reset of sui_settings.lua.\
                    and k ~= \"simpleui_userdata_migrated_v1\"\
                if owned then\
                    to_migrate[#to_migrate + 1] = { k = k, v = v }\
                end\
            end\
\
            local migrated = 0\
            for _, entry in ipairs(to_migrate) do\
                local k, v = entry.k, entry.v\
                -- Only copy if SUISettings does not already have the key\
                -- (e.g. the user already made changes after the code update).\
                if SUISettings:get(k) == nil then\
                    SUISettings:set(k, v)\
                end\
                G_reader_settings:delSetting(k)\
                migrated = migrated + 1\
            end\
\
            SUISettings:flush()\
            logger.info(\"simpleui: settings migration v2 complete —\", migrated, \"keys moved to SUISettings\")\
        end)\
        SUISettings:set(\"simpleui_settings_migrated_v2\", true)\
        SUISettings:flush()\
    end\
    -- -------------------------------------------------------------------\
    -- Settings migration v3: rename all navbar_* keys inside SUISettings\
    -- to the canonical simpleui_* namespace.\
    --\
    -- Two passes:\
    --   1. Fixed renames  — explicit old → new map (fast, readable).\
    --   2. Dynamic prefix — bulk rename of per-slot / per-id keys that are\
    --      built at runtime via string concatenation.\
    --\
    -- Rules:\
    --   • Only copies when the destination key is absent (never overwrites).\
    --   • Old key is always deleted, even when the copy is skipped.\
    --   • The whole block runs inside pcall — a crash must never prevent\
    --     the plugin from loading on a resource-constrained e-reader.\
    --   • Guarded by simpleui_settings_migrated_v3 so it runs at most once.\
    -- -------------------------------------------------------------------\
    if not SUISettings:isTrue(\"simpleui_settings_migrated_v3\") then\
        pcall(function()\
            -- ── 1. Fixed renames ─────────────────────────────────────────\
            local fixed_renames = {\
                -- Bottom bar — general\
                { \"navbar_enabled\",                      \"simpleui_bar_enabled\"                   },\
                { \"navbar_mode\",                         \"simpleui_bar_mode\"                      },\
                { \"navbar_bar_size\",                     \"simpleui_bar_size\"                      },\
                { \"navbar_bar_size_pct\",                 \"simpleui_bar_size_pct\"                  },\
                { \"navbar_hide_separator\",               \"simpleui_bar_hide_separator\"            },\
                { \"navbar_bottom_margin_pct\",            \"simpleui_bar_bottom_margin_pct\"         },\
                { \"navbar_icon_scale_pct\",               \"simpleui_bar_icon_scale_pct\"            },\
                { \"navbar_label_scale_pct\",              \"simpleui_bar_label_scale_pct\"           },\
                { \"navbar_rs_text_scale_pct\",            \"simpleui_bar_rs_text_scale_pct\"         },\
                -- Bottom bar — pagination / pager\
                { \"navbar_pagination_visible\",           \"simpleui_bar_pagination_visible\"        },\
                { \"navbar_pagination_size\",              \"simpleui_bar_pagination_size\"           },\
                { \"navbar_pagination_show_subtitle\",     \"simpleui_bar_pagination_show_subtitle\"  },\
                { \"navbar_navpager_enabled\",             \"simpleui_bar_navpager_enabled\"          },\
                { \"navbar_dotpager_always\",              \"simpleui_bar_dotpager_always\"           },\
                -- Bottom bar — tabs & settings\
                { \"navbar_tabs\",                         \"simpleui_bar_tabs\"                      },\
                { \"navbar_bottombar_settings_on_hold\",   \"simpleui_bar_settings_on_hold\"          },\
                -- Top bar\
                { \"navbar_topbar_enabled\",               \"simpleui_topbar_enabled\"                },\
                { \"navbar_topbar_config\",                \"simpleui_topbar_config\"                 },\
                { \"navbar_topbar_custom_text\",           \"simpleui_topbar_custom_text\"            },\
                { \"navbar_topbar_settings_on_hold\",      \"simpleui_topbar_settings_on_hold\"       },\
                { \"navbar_topbar_swipe_indicator\",       \"simpleui_topbar_swipe_indicator\"        },\
                { \"navbar_topbar_wifi_hide_when_off\",    \"simpleui_topbar_wifi_hide_when_off\"     },\
                { \"navbar_topbar_size_pct\",              \"simpleui_topbar_size_pct\"               },\
                -- Homescreen bar — fixed keys\
                { \"navbar_homescreen_pagination_hidden\", \"simpleui_hs_pagination_hidden\"          },\
                { \"navbar_homescreen_settings_on_hold\",  \"simpleui_hs_settings_on_hold\"           },\
                { \"navbar_homescreen_overflow_warn\",     \"simpleui_hs_overflow_warn\"              },\
                { \"navbar_hs_return_to_book_folder\",     \"simpleui_hs_return_to_book_folder\"      },\
                { \"navbar_homescreen_module_scale\",      \"simpleui_hs_module_scale\"               },\
                { \"navbar_homescreen_label_scale\",       \"simpleui_hs_label_scale\"                },\
                { \"navbar_homescreen_scale_linked\",      \"simpleui_hs_scale_linked\"               },\
                -- Reading goal\
                { \"navbar_reading_goal\",                 \"simpleui_reading_goal\"                  },\
                { \"navbar_reading_goal_physical\",        \"simpleui_reading_goal_physical\"         },\
                { \"navbar_daily_reading_goal_secs\",      \"simpleui_daily_reading_goal_secs\"       },\
                -- Reading goals module display\
                { \"navbar_reading_goals_show_annual\",    \"simpleui_reading_goals_show_annual\"     },\
                { \"navbar_reading_goals_show_daily\",     \"simpleui_reading_goals_show_daily\"      },\
                { \"navbar_reading_goals_layout\",         \"simpleui_reading_goals_layout\"          },\
                -- Collections module\
                { \"navbar_collections_list\",             \"simpleui_collections_list\"              },\
                { \"navbar_collections_covers\",           \"simpleui_collections_covers\"            },\
                { \"navbar_collections_badge_position\",   \"simpleui_collections_badge_position\"    },\
                { \"navbar_collections_badge_color\",      \"simpleui_collections_badge_color\"       },\
                { \"navbar_collections_badge_hidden\",     \"simpleui_collections_badge_hidden\"      },\
                -- Custom quick actions — list & migration flag\
                { \"navbar_custom_qa_list\",               \"simpleui_cqa_list\"                      },\
                { \"navbar_custom_qa_migrated_v1\",        \"simpleui_cqa_migrated_v1\"               },\
            }\
\
            local migrated = 0\
\
            for _, pair in ipairs(fixed_renames) do\
                local old_k, new_k = pair[1], pair[2]\
                local val = SUISettings:get(old_k)\
                if val ~= nil then\
                    if SUISettings:get(new_k) == nil then\
                        SUISettings:set(new_k, val)\
                    end\
                    SUISettings:del(old_k)\
                    migrated = migrated + 1\
                end\
            end\
\
            -- ── 2. Dynamic-prefix renames ─────────────────────────────────\
            -- Keys built at runtime via string concatenation:\
            --   simpleui_hs_*        (was navbar_homescreen_*)\
            --   navbar_cqa_*         →  simpleui_cqa_*\
            --   navbar_action_*      →  simpleui_action_*\
            --   navbar_custom_*      →  simpleui_custom_*\
            --\
            -- We collect all renames first, then apply — modifying a table\
            -- while iterating it is undefined behaviour in Lua 5.1/5.2.\
            local dynamic_prefixes = {\
                { old = \"navbar_homescreen_\",  new = \"simpleui_hs_\"     },\
                { old = \"navbar_cqa_\",         new = \"simpleui_cqa_\"    },\
                { old = \"navbar_action_\",      new = \"simpleui_action_\" },\
                { old = \"navbar_custom_\",      new = \"simpleui_custom_\" },\
            }\
\
            local pending = {}\
            for k, v in SUISettings:iterateKeys() do\
                for _, pfx in ipairs(dynamic_prefixes) do\
                    local plen = #pfx.old\
                    if k:sub(1, plen) == pfx.old then\
                        local new_k = pfx.new .. k:sub(plen + 1)\
                        pending[#pending + 1] = { old_k = k, new_k = new_k, val = v }\
                        break\
                    end\
                end\
            end\
\
            for _, entry in ipairs(pending) do\
                if SUISettings:get(entry.new_k) == nil then\
                    SUISettings:set(entry.new_k, entry.val)\
                end\
                SUISettings:del(entry.old_k)\
                migrated = migrated + 1\
            end\
\
            SUISettings:flush()\
            logger.info(\"simpleui: settings migration v3 complete —\", migrated, \"navbar_* keys renamed to simpleui_*\")\
        end)\
        SUISettings:set(\"simpleui_settings_migrated_v3\", true)\
        SUISettings:flush()\
    end\
    -- -------------------------------------------------------------------\
    -- Settings migration v4: rename icon pack keys to integrated sui_ scheme.\
    -- -------------------------------------------------------------------\
    if not SUISettings:isTrue(\"simpleui_settings_migrated_v4\") then\
        pcall(function()\
            local icon_renames = {\
                { \"simpleui_sysicon_bm_normal\",     \"simpleui_sysicon_sui_browse_normal\" },\
                { \"simpleui_sysicon_bm_author\",     \"simpleui_sysicon_sui_browse_author\" },\
                { \"simpleui_sysicon_bm_series\",     \"simpleui_sysicon_sui_browse_series\" },\
                { \"simpleui_sysicon_bm_tags\",       \"simpleui_sysicon_sui_browse_tags\" },\
                { \"simpleui_sysicon_pg_chev_left\",  \"simpleui_sysicon_sui_pager_prev\" },\
                { \"simpleui_sysicon_pg_chev_right\", \"simpleui_sysicon_sui_pager_next\" },\
                { \"simpleui_sysicon_pg_chev_first\", \"simpleui_sysicon_sui_pager_first\" },\
                { \"simpleui_sysicon_pg_chev_last\",  \"simpleui_sysicon_sui_pager_last\" },\
                { \"simpleui_sysicon_coll_back\",     \"simpleui_sysicon_sui_coll_back\" },\
            }\
            local migrated = 0\
            for _, pair in ipairs(icon_renames) do\
                local old_k, new_k = pair[1], pair[2]\
                local val = SUISettings:get(old_k)\
                if val ~= nil then\
                    if SUISettings:get(new_k) == nil then\
                        SUISettings:set(new_k, val)\
                    end\
                    SUISettings:del(old_k)\
                    migrated = migrated + 1\
                end\
            end\
            local icon_presets = SUISettings:get(\"simpleui_icon_presets\")\
            if type(icon_presets) == \"table\" then\
                local changed = false\
                for _, preset in pairs(icon_presets) do\
                    if type(preset._scalar) == \"table\" then\
                        for _, pair in ipairs(icon_renames) do\
                            local old_k, new_k = pair[1], pair[2]\
                            if preset._scalar[old_k] ~= nil then\
                                if preset._scalar[new_k] == nil then\
                                    preset._scalar[new_k] = preset._scalar[old_k]\
                                end\
                                preset._scalar[old_k] = nil\
                                changed = true\
                            end\
                        end\
                    end\
                end\
                if changed then SUISettings:set(\"simpleui_icon_presets\", icon_presets) end\
            end\
            SUISettings:flush()\
            logger.info(\"simpleui: settings migration v4 complete —\", migrated, \"icon keys renamed\")\
        end)\
        SUISettings:set(\"simpleui_settings_migrated_v4\", true)\
        SUISettings:flush()\
    end\
    -- -------------------------------------------------------------------\
    -- Settings migration v5: standardize titlebar button nomenclature\
    -- -------------------------------------------------------------------\
    if not SUISettings:isTrue(\"simpleui_settings_migrated_v5\") then\
        pcall(function()\
            local renames = {\
                { \"simpleui_tb_item_menu_button\",     \"simpleui_tb_item_fm_menu\" },\
                { \"simpleui_tb_item_up_button\",       \"simpleui_tb_item_fm_back\" },\
                { \"simpleui_tb_item_search_button\",   \"simpleui_tb_item_fm_search\" },\
                { \"simpleui_tb_item_browse_button\",   \"simpleui_tb_item_fm_browse\" },\
                { \"simpleui_tb_item_title\",           \"simpleui_tb_item_fm_title\" },\
                { \"simpleui_tb_item_inj_back\",        \"simpleui_tb_item_sub_menu\" },\
                { \"simpleui_tb_item_inj_right\",       \"simpleui_tb_item_sub_close\" },\
                { \"simpleui_tb_item_inj_menubutton\",  \"simpleui_tb_item_sub_menu\" },\
                { \"simpleui_tb_item_inj_closebutton\", \"simpleui_tb_item_sub_close\" },\
                { \"simpleui_tb_inj_cfg\",              \"simpleui_tb_sub_cfg\" },\
            }\
            local migrated = 0\
            for _, pair in ipairs(renames) do\
                local old_k, new_k = pair[1], pair[2]\
                local val = SUISettings:get(old_k)\
                if val ~= nil then\
                    if SUISettings:get(new_k) == nil then\
                        SUISettings:set(new_k, val)\
                    end\
                    SUISettings:del(old_k)\
                    migrated = migrated + 1\
                end\
            end\
\
            local function map_cfg(cfg_key, mapping)\
                local cfg = SUISettings:get(cfg_key)\
                if type(cfg) == \"table\" then\
                    local changed = false\
                    local function map_arr(arr)\
                        for i, v in ipairs(arr) do\
                            if mapping[v] then arr[i] = mapping[v]; changed = true end\
                        end\
                    end\
                    if type(cfg.side) == \"table\" then\
                        for old_btn, new_btn in pairs(mapping) do\
                            if cfg.side[old_btn] ~= nil then\
                                cfg.side[new_btn] = cfg.side[old_btn]\
                                cfg.side[old_btn] = nil\
                                changed = true\
                            end\
                        end\
                    end\
                    if type(cfg.order_left) == \"table\" then map_arr(cfg.order_left) end\
                    if type(cfg.order_right) == \"table\" then map_arr(cfg.order_right) end\
                    if changed then\
                        SUISettings:set(cfg_key, cfg)\
                        migrated = migrated + 1\
                    end\
                end\
            end\
\
            local fm_map = {\
                menu_button   = \"fm_menu\",\
                up_button     = \"fm_back\",\
                search_button = \"fm_search\",\
                browse_button = \"fm_browse\",\
                title         = \"fm_title\"\
            }\
            local sub_map = {\
                inj_back         = \"sub_menu\",\
                inj_right        = \"sub_close\",\
                inj_menubutton   = \"sub_menu\",\
                inj_closebutton  = \"sub_close\"\
            }\
            map_cfg(\"simpleui_tb_fm_cfg\", fm_map)\
            map_cfg(\"simpleui_tb_sub_cfg\", sub_map)\
\
            logger.info(\"simpleui: settings migration v5 complete —\", migrated, \"titlebar keys renamed\")\
        end)\
        SUISettings:set(\"simpleui_settings_migrated_v5\", true)\
        SUISettings:flush()\
    end\
    -- -------------------------------------------------------------------\
    -- Settings migration v6: namespace clean-up and key standardisation.\
    --\
    -- Changes applied:\
    --   1. Module enabled_key unification — bare module IDs (e.g. \"currently\",\
    --      \"recent\", \"coverdeck\", \"tbr\", \"new_books\", \"collections\",\
    --      \"reading_goals\") gain an explicit \"_enabled\" suffix to match the\
    --      convention already used by clock, reading_stats, action_list, etc.\
    --\
    --   2. module_coverdeck \"flow_\" prefix → \"coverdeck_\" prefix — the old\
    --      keys had no \"simpleui_\" namespace and risked collisions in the\
    --      shared G_reader_settings / SUISettings store.\
    --\
    --   3. simpleui_cqa_* → simpleui_qa_* — \"cqa\" was undocumented jargon;\
    --      \"qa\" matches the term used throughout the UI.  Also covers the\
    --      per-slot dynamic keys simpleui_cqa_{id} → simpleui_qa_{id}.\
    --\
    --   4. simpleui_collections_* → simpleui_coll_* — shorter, consistent\
    --      with the \"fc_\" brevity used by foldercovers.\
    --\
    --   5. simpleui_titlebar_custom → simpleui_tb_custom — aligns with the\
    --      tb_ alias used by all other titlebar keys.\
    --\
    --   6. simpleui_tb_size → simpleui_tb_size_pct — consistent with the\
    --      other size percentage keys (_bar_size_pct, _topbar_size_pct).\
    --\
    --   7. simpleui_bar_size (legacy enum \"default\"|\"large\") removed — this\
    --      key was only written by first-run defaults v1 and was never read\
    --      by any code path; the canonical value is simpleui_bar_size_pct.\
    --\
    -- Rules (identical to all previous migrations):\
    --   • Copy only when destination key is absent (never overwrite).\
    --   • Always delete the source key, even when copy is skipped.\
    --   • Whole block in pcall — a crash must not prevent plugin load.\
    --   • Guarded by simpleui_settings_migrated_v6.\
    -- -------------------------------------------------------------------\
    if not SUISettings:isTrue(\"simpleui_settings_migrated_v6\") then\
        pcall(function()\
            local migrated = 0\
\
            -- ── Helper: rename a single key ───────────────────────────\
            local function _rename(old_k, new_k)\
                local val = SUISettings:get(old_k)\
                if val ~= nil then\
                    if SUISettings:get(new_k) == nil then\
                        SUISettings:set(new_k, val)\
                    end\
                    SUISettings:del(old_k)\
                    migrated = migrated + 1\
                end\
            end\
\
            -- ── 1. Module enabled_key: add _enabled suffix ────────────\
            -- For each preset prefix that exists in SUISettings, rename\
            -- the bare module-id keys to module-id_enabled.\
            -- The only guaranteed preset prefix is \"simpleui_hs_\" but\
            -- user presets can have arbitrary prefixes — we scan all keys.\
            local bare_mods = {\
                \"currently\", \"recent\", \"coverdeck\",\
                \"tbr\", \"new_books\", \"collections\", \"reading_goals\",\
            }\
            -- Collect all unique prefixes that have at least one of the\
            -- bare keys so we don't have to hardcode \"simpleui_hs_\".\
            local prefixes_seen = {}\
            for k, _ in SUISettings:iterateKeys() do\
                if type(k) == \"string\" then\
                    for _, mod_id in ipairs(bare_mods) do\
                        -- key must end exactly with the bare mod_id\
                        -- (no trailing chars) to avoid false matches\
                        local sfx = mod_id\
                        local klen, slen = #k, #sfx\
                        if klen > slen and k:sub(klen - slen + 1) == sfx\
                                and k:sub(klen - slen) == \"_\" then\
                            local pfx = k:sub(1, klen - slen)\
                            prefixes_seen[pfx] = true\
                        end\
                    end\
                end\
            end\
            for pfx in pairs(prefixes_seen) do\
                for _, mod_id in ipairs(bare_mods) do\
                    _rename(pfx .. mod_id, pfx .. mod_id .. \"_enabled\")\
                end\
            end\
\
            -- ── 2. module_coverdeck: flow_ → coverdeck_ ───────────────\
            -- These keys are prefixed with a homescreen preset prefix\
            -- (e.g. \"simpleui_hs_\") at runtime, so we scan all keys.\
            local flow_suffixes = {\
                \"flow_recent_source\",\
                \"flow_stats_order\",\
                -- flow_show_{elem} keys are boolean per-element toggles;\
                -- we catch them with the dynamic scan below.\
            }\
            local flow_pending = {}\
            for k, v in SUISettings:iterateKeys() do\
                if type(k) == \"string\" then\
                    -- Fixed suffixes\
                    for _, sfx in ipairs(flow_suffixes) do\
                        if k:sub(- #sfx) == sfx then\
                            local pfx = k:sub(1, #k - #sfx)\
                            local new_sfx = sfx\
                                :gsub(\"^flow_recent_source$\", \"coverdeck_source\")\
                                :gsub(\"^flow_stats_order$\",   \"coverdeck_stats_order\")\
                            flow_pending[#flow_pending + 1] = {\
                                old_k = k, new_k = pfx .. new_sfx, val = v\
                            }\
                            break\
                        end\
                    end\
                    -- Dynamic: flow_show_{anything} → coverdeck_show_{anything}\
                    local tail = k:match(\"_flow_show_(.+)$\")\
                    if tail then\
                        local pfx = k:sub(1, #k - #(\"flow_show_\" .. tail))\
                        flow_pending[#flow_pending + 1] = {\
                            old_k = k,\
                            new_k = pfx .. \"coverdeck_show_\" .. tail,\
                            val   = v,\
                        }\
                    end\
                end\
            end\
            for _, e in ipairs(flow_pending) do\
                if SUISettings:get(e.new_k) == nil then\
                    SUISettings:set(e.new_k, e.val)\
                end\
                SUISettings:del(e.old_k)\
                migrated = migrated + 1\
            end\
\
            -- ── 3. simpleui_cqa_* → simpleui_qa_* ────────────────────\
            -- Covers: simpleui_cqa_list, simpleui_cqa_migrated_v1,\
            --         simpleui_cqa_custom_qa_{n}, simpleui_cqa_{id}\
            -- The migration-v3 target was \"simpleui_cqa_*\"; we now move\
            -- those to \"simpleui_qa_*\".\
            local cqa_pending = {}\
            for k, v in SUISettings:iterateKeys() do\
                if type(k) == \"string\" and k:sub(1, 13) == \"simpleui_cqa_\" then\
                    cqa_pending[#cqa_pending + 1] = {\
                        old_k = k,\
                        new_k = \"simpleui_qa_\" .. k:sub(14),\
                        val   = v,\
                    }\
                end\
            end\
            for _, e in ipairs(cqa_pending) do\
                if SUISettings:get(e.new_k) == nil then\
                    SUISettings:set(e.new_k, e.val)\
                end\
                SUISettings:del(e.old_k)\
                migrated = migrated + 1\
            end\
            -- Also fix the migration guard written by migrateOldCustomSlots.\
            _rename(\"simpleui_cqa_migrated_v1\", \"simpleui_qa_migrated_v1\")\
\
            -- ── 4. simpleui_collections_* → simpleui_coll_* ──────────\
            local coll_renames = {\
                { \"simpleui_collections_list\",           \"simpleui_coll_list\"           },\
                { \"simpleui_collections_covers\",         \"simpleui_coll_covers\"         },\
                { \"simpleui_collections_badge_position\", \"simpleui_coll_badge_position\" },\
                { \"simpleui_collections_badge_color\",    \"simpleui_coll_badge_color\"    },\
                { \"simpleui_collections_badge_hidden\",   \"simpleui_coll_badge_hidden\"   },\
            }\
            for _, pair in ipairs(coll_renames) do\
                _rename(pair[1], pair[2])\
            end\
\
            -- ── 5. simpleui_titlebar_custom → simpleui_tb_custom ──────\
            _rename(\"simpleui_titlebar_custom\", \"simpleui_tb_custom\")\
\
            -- ── 6. simpleui_tb_size → simpleui_tb_size_pct ───────────\
            _rename(\"simpleui_tb_size\", \"simpleui_tb_size_pct\")\
\
            -- ── 7. Remove legacy simpleui_bar_size enum ───────────────\
            -- Never read by any code; only written by first-run defaults v1.\
            -- The canonical value is simpleui_bar_size_pct.\
            SUISettings:del(\"simpleui_bar_size\")\
\
            SUISettings:flush()\
            logger.info(\"simpleui: settings migration v6 complete —\", migrated, \"keys renamed/removed\")\
        end)\
        SUISettings:set(\"simpleui_settings_migrated_v6\", true)\
        SUISettings:flush()\
    end\
    -- -------------------------------------------------------------------\
\
    -- Settings migration v7:\
    -- 1. Restore coverdeck_show_title when written as false by the\
    --    \"Momentum\" preset but never explicitly toggled by the user.\
    --    Detects the exact Momentum signature (title=false, author=false,\
    --    progress=true, percent=true, book_days=true) and resets to true.\
    -- 2. Enable recent_show_finished when it has never been set, so users\
    --    upgrading from 1.5.x (where the filter did not exist) don't find\
    --    Recent Books / Cover Deck empty because all their books are at 100%.\
    -- 3. Enable the automatic update check when it has never been set,\
    --    making auto-check opt-out instead of opt-in.\
    if not SUISettings:isTrue(\"simpleui_settings_migrated_v7\") then\
        pcall(function()\
            local PFX       = \"simpleui_hs_\"\
            -- 1. coverdeck_show_title\
            local title     = SUISettings:get(PFX .. \"coverdeck_show_title\")\
            local author    = SUISettings:get(PFX .. \"coverdeck_show_author\")\
            local progress  = SUISettings:get(PFX .. \"coverdeck_show_progress\")\
            local percent   = SUISettings:get(PFX .. \"coverdeck_show_percent\")\
            local book_days = SUISettings:get(PFX .. \"coverdeck_show_book_days\")\
            if title == false and author == false\
                    and progress == true and percent == true\
                    and book_days == true then\
                SUISettings:set(PFX .. \"coverdeck_show_title\", true)\
                logger.info(\"simpleui: migration v7 — restored coverdeck_show_title to true\")\
            end\
            -- 2. recent_show_finished\
            if SUISettings:get(PFX .. \"recent_show_finished\") == nil then\
                SUISettings:set(PFX .. \"recent_show_finished\", true)\
                logger.info(\"simpleui: migration v7 — enabled recent_show_finished\")\
            end\
            -- 3. auto update check\
            if SUISettings:get(\"simpleui_updater_auto_check\") == nil then\
                SUISettings:set(\"simpleui_updater_auto_check\", true)\
                logger.info(\"simpleui: migration v7 — enabled simpleui_updater_auto_check\")\
            end\
        end)\
        SUISettings:set(\"simpleui_settings_migrated_v7\", true)\
        SUISettings:flush()\
    end\
    -- -------------------------------------------------------------------\
\
    -- Settings migration v8:\
    -- Introduces the unified Cover Deck arrange list (coverdeck_main_order),\
    -- replacing the old coverdeck_title_pos above/below/hidden radio and\
    -- the separate \"Show status bar\" toggle for the progress bar.\
    --   1. Legacy title_pos == \"hidden\" had no dedicated key of its own;\
    --      fold it into coverdeck_show_title so upgrading users keep the\
    --      title hidden instead of it reappearing under the new model.\
    --   2. coverdeck_main_order is seeded from title_pos (\"above\"/\"below\")\
    --      so existing layouts render identically the first time they're\
    --      opened under the new arrange list, instead of silently\
    --      reverting to the \"below\" default.\
    if not SUISettings:isTrue(\"simpleui_settings_migrated_v8\") then\
        pcall(function()\
            local PFX       = \"simpleui_hs_\"\
            local title_pos = SUISettings:get(PFX .. \"coverdeck_title_pos\")\
            if title_pos == \"hidden\" and SUISettings:get(PFX .. \"coverdeck_show_title\") == nil then\
                SUISettings:set(PFX .. \"coverdeck_show_title\", false)\
                logger.info(\"simpleui: migration v8 — folded coverdeck_title_pos=hidden into coverdeck_show_title=false\")\
            end\
            if SUISettings:get(PFX .. \"coverdeck_main_order\") == nil then\
                local order = (title_pos == \"above\")\
                    and { \"title\", \"author\", \"covers\", \"progress\", \"stats\" }\
                    or  { \"covers\", \"title\", \"author\", \"progress\", \"stats\" }\
                SUISettings:set(PFX .. \"coverdeck_main_order\", order)\
                logger.info(\"simpleui: migration v8 — seeded coverdeck_main_order from legacy title_pos\")\
            end\
        end)\
        SUISettings:set(\"simpleui_settings_migrated_v8\", true)\
        SUISettings:flush()\
    end\
    -- -------------------------------------------------------------------\
\
    -- Settings migration v9:\
    -- Selects the tabs title bar style when no style was ever chosen.\
    -- An explicit choice, including classic, is kept.\
    if not SUISettings:isTrue(\"simpleui_settings_migrated_v9\") then\
        pcall(function()\
            if SUISettings:get(\"simpleui_tb_style\") == nil then\
                SUISettings:set(\"simpleui_tb_style\", \"tabs\")\
                logger.info(\"simpleui: migration v9 — title bar style set to tabs\")\
            end\
        end)\
        SUISettings:set(\"simpleui_settings_migrated_v9\", true)\
        SUISettings:flush()\
    end\
    -- -------------------------------------------------------------------\
\
    -- Settings migration v10:\
    -- Folds the finished-books fade toggle into the three-state mode\
    -- (show / fade / hide). An explicit \"off\" becomes \"show\"; any other\
    -- stored value keeps the previous behaviour, \"fade\".\
    if not SUISettings:isTrue(\"simpleui_settings_migrated_v10\") then\
        pcall(function()\
            local legacy = SUISettings:get(\"simpleui_fc_fade_finished\")\
            if legacy == nil then return end\
            if SUISettings:get(\"simpleui_fc_finished_mode\") == nil then\
                SUISettings:set(\"simpleui_fc_finished_mode\", legacy == false and \"show\" or \"fade\")\
            end\
            SUISettings:del(\"simpleui_fc_fade_finished\")\
            logger.info(\"simpleui: migration v10 — folded finished-books fade toggle into the mode\")\
        end)\
        SUISettings:set(\"simpleui_settings_migrated_v10\", true)\
        SUISettings:flush()\
    end\
    -- -------------------------------------------------------------------\
\
    -- Settings migration v11:\
    -- Series grouping becomes a per-view setting. An enabled global flag\
    -- enables it in every view that supported it, keeping the previous\
    -- behaviour; the global flag is then dropped.\
    if not SUISettings:isTrue(\"simpleui_settings_migrated_v11\") then\
        pcall(function()\
            local legacy_key = \"simpleui_fc_series_grouping\"\
            local legacy = SUISettings:get(legacy_key)\
            if legacy == nil then return end\
            for _, mode in ipairs({ \"normal\", \"author\", \"tags\" }) do\
                local key = legacy_key .. \"_\" .. mode\
                if SUISettings:get(key) == nil then SUISettings:set(key, legacy == true) end\
            end\
            SUISettings:del(legacy_key)\
            logger.info(\"simpleui: migration v11 — series grouping split per view\")\
        end)\
        SUISettings:set(\"simpleui_settings_migrated_v11\", true)\
        SUISettings:flush()\
    end\
    -- -------------------------------------------------------------------\
\
    -- Settings migration v12:\
    -- Library badge settings move to the cover elements registry: the\
    -- combined visibility/variant enums split into `show` + variant and\
    -- the keys gain the \"simpleui_style_badge_\" prefix.\
    if not SUISettings:isTrue(\"simpleui_settings_migrated_v12\") then\
        pcall(function()\
            require(\"features/sui_cover_elements\").migrateLegacyBadges()\
        end)\
        SUISettings:set(\"simpleui_settings_migrated_v12\", true)\
        SUISettings:flush()\
    end\
    -- -------------------------------------------------------------------\
\
    -- Settings migration v13:\
    -- Folder cover settings move to the cover elements registry (the name\
    -- visibility enums merge into `show`, the stack's `hide` becomes\
    -- `show`) and the library caption flags to the captions keys.\
    if not SUISettings:isTrue(\"simpleui_settings_migrated_v13\") then\
        pcall(function()\
            require(\"features/sui_cover_elements\").migrateLegacyFolder()\
        end)\
        pcall(function()\
            require(\"features/library/sui_foldercovers\").migrateLegacyCaptions()\
        end)\
        SUISettings:set(\"simpleui_settings_migrated_v13\", true)\
        SUISettings:flush()\
    end\
    -- -------------------------------------------------------------------\
\
    -- Settings migration v14:\
    -- The critter, its bubble style, phrase source, topics and reactions\
    -- become global settings, taken from the default screen's.\
    if not SUISettings:isTrue(\"simpleui_settings_migrated_v14\") then\
        pcall(function()\
            require(\"modules/critter/settings\").migrateLegacy()\
        end)\
        SUISettings:set(\"simpleui_settings_migrated_v14\", true)\
        SUISettings:flush()\
    end\
    -- -------------------------------------------------------------------\
end\
\
return M\
",
    ["modules/critter/book"] = "-- book.lua — Simple UI\
-- The book the Critter module talks about: the one read last, when it is\
-- started and not finished.\
\
local lfs = require(\"libs/libkoreader-lfs\")\
\
local Book = {}\
\
local DAY_SECS = 24 * 3600\
\
--- Facts of a book for the phrases, { title, percent, days }: its progress in\
--- whole percent and the whole days since `last_read`. nil when the book was\
--- not started or is finished. `fraction` is the progress from 0 to 1.\
function Book.facts(title, fraction, last_read, now)\
    if type(title) ~= \"string\" or type(last_read) ~= \"number\" or type(now) ~= \"number\" then return nil end\
    local percent = math.floor((fraction or 0) * 100)\
    if percent < 1 or percent > 99 then return nil end\
    return {\
        title   = title,\
        percent = percent,\
        days    = math.max(0, math.floor((now - last_read) / DAY_SECS)),\
    }\
end\
\
--- Facts (see Book.facts) of the book read last, nil when there is none.\
function Book.current(now)\
    local ReadHistory = package.loaded[\"readhistory\"] or require(\"readhistory\")\
    local hist = ReadHistory and ReadHistory.hist\
    if not hist then return nil end\
    local SH = require(\"modules/module_books_shared\")\
    local hidden = require(\"features/library/sui_recent_hidden\").snapshot()\
    for i = 1, math.min(30, #hist) do\
        local entry = hist[i]\
        if entry.file and not hidden[entry.file] and lfs.attributes(entry.file, \"mode\") == \"file\" then\
            local book = SH.getBookData(entry.file)\
            if book.status == \"complete\" then return nil end\
            return Book.facts(book.title, book.percent, entry.time, now)\
        end\
    end\
    return nil\
end\
\
return Book\
",
    ["modules/critter/game_lines"] = "-- game_lines.lua — Simple UI\
-- What the Critter says while it plays (games.lua) and when it reads a quote\
-- (talk.lua). A set of lines holds `base` and, where the attitude changes, the\
-- mood tiers of dialog.lua that override it; every line is a function so it is\
-- translated when it is shown. Same voice and length rules as dialog.lua.\
\
local _ = require(\"infra/sui_i18n\").translate\
\
local GameLines = {}\
\
-- Mood of the critter's closing line for each tier; the other tiers play.\
local TIER_MOOD = { grumpy = \"grumpy\", happy = \"cheer\", radiant = \"love\" }\
\
-- The line of `set` for `tier`.\
local function line(set, tier)\
    return (set[tier] or set.base)()\
end\
\
-- Outcome lines of a round, as { win | lose | draw, or right | wrong = set }.\
local RPS = {\
    win = {\
        base    = function() return _(\"You win. This time.\") end,\
        grumpy  = function() return _(\"You win. Hmph.\") end,\
        radiant = function() return _(\"You win! You're too good.\") end,\
    },\
    lose = {\
        base    = function() return _(\"I win.\") end,\
        grumpy  = function() return _(\"I win. Obviously.\") end,\
        radiant = function() return _(\"I win! Want to try again?\") end,\
    },\
    draw = {\
        base    = function() return _(\"A draw.\") end,\
        grumpy  = function() return _(\"A draw. Boring.\") end,\
        radiant = function() return _(\"A draw! We think alike.\") end,\
    },\
}\
\
local COIN = {\
    right = {\
        base    = function() return _(\"You called it.\") end,\
        grumpy  = function() return _(\"Lucky guess.\") end,\
        radiant = function() return _(\"You called it! Of course you did.\") end,\
    },\
    wrong = {\
        base    = function() return _(\"Not this time.\") end,\
        grumpy  = function() return _(\"Wrong. Next.\") end,\
        radiant = function() return _(\"Not this time. Again?\") end,\
    },\
}\
\
local QUIZ = {\
    right = {\
        base    = function() return _(\"Correct!\") end,\
        grumpy  = function() return _(\"Correct. Don't let it go to your head.\") end,\
        radiant = function() return _(\"Correct! You know your books.\") end,\
    },\
    wrong = {\
        base    = function(author) return string.format(_(\"It was %s.\"), author) end,\
        grumpy  = function(author) return string.format(_(\"Wrong. It was %s.\"), author) end,\
        radiant = function(author) return string.format(_(\"Close! It was %s.\"), author) end,\
    },\
}\
\
local DONE = {\
    base    = function() return _(\"Good game. Same time tomorrow?\") end,\
    grumpy  = function() return _(\"Fine. That's enough for me too.\") end,\
    radiant = function() return _(\"I love playing with you.\") end,\
}\
\
-- Comments on a quote the critter has read; one is dealt at random.\
local COMMENTS = {\
    base = {\
        function() return _(\"I'll keep that one on the shelf.\") end,\
        function() return _(\"Someone wrote that on purpose.\") end,\
        function() return _(\"I'll think about that all night.\") end,\
        function() return _(\"Short. Good. My kind of sentence.\") end,\
    },\
    grumpy = {\
        function() return _(\"Hm. I've read worse.\") end,\
        function() return _(\"Fine. That one can stay.\") end,\
    },\
    happy = {\
        function() return _(\"Oh, I like that one.\") end,\
        function() return _(\"That one made my day a little bigger.\") end,\
    },\
    radiant = {\
        function() return _(\"That's beautiful. Read it again?\") end,\
        function() return _(\"I want to frame that one.\") end,\
    },\
}\
\
function GameLines.menuPrompt() return _(\"What shall we play?\") end\
function GameLines.rpsText()    return _(\"Rock, paper, scissors\") end\
function GameLines.coinText()   return _(\"Heads or tails\") end\
function GameLines.quizText()   return _(\"Guess the author\") end\
\
function GameLines.rpsPrompt()  return _(\"Rock, paper, scissors. Go.\") end\
function GameLines.coinPrompt() return _(\"I'm flipping. Call it.\") end\
\
function GameLines.quizPrompt(quote)\
    return string.format(_(\"Who said “%s”?\"), quote)\
end\
\
local NAMES = {\
    rock     = function() return _(\"Rock\") end,\
    paper    = function() return _(\"Paper\") end,\
    scissors = function() return _(\"Scissors\") end,\
    heads    = function() return _(\"Heads\") end,\
    tails    = function() return _(\"Tails\") end,\
}\
\
--- Name of a move (rock, paper, scissors) or a side of the coin (heads, tails).\
function GameLines.name(id) return NAMES[id]() end\
\
--- What the critter says after a round of rock, paper, scissors: its move and\
--- the outcome (\"win\" | \"lose\" | \"draw\", for the user).\
function GameLines.rpsResult(move, outcome, tier)\
    return string.format(\"%s! %s\", GameLines.name(move), line(RPS[outcome], tier))\
end\
\
--- After a toss: the side it landed on and whether the user called it.\
function GameLines.coinResult(side, right, tier)\
    return string.format(\"%s! %s\", GameLines.name(side), line(COIN[right and \"right\" or \"wrong\"], tier))\
end\
\
--- After a \"who said it?\" question.\
function GameLines.quizResult(right, author, tier)\
    local set = QUIZ[right and \"right\" or \"wrong\"]\
    return (set[tier] or set.base)(author)\
end\
\
function GameLines.again()      return _(\"Another round\") end\
function GameLines.anotherOne() return _(\"Another one\") end\
function GameLines.enough()     return _(\"Enough for now\") end\
\
--- The reply that ends a game, { mood, text }.\
function GameLines.done(tier)\
    return { mood = TIER_MOOD[tier] or \"playful\", text = line(DONE, tier) }\
end\
\
--- A quote as the critter reads it, with its author when it has one.\
function GameLines.quoteText(entry)\
    if not entry.a then return string.format(\"“%s”\", entry.q) end\
    return string.format(\"“%s” — %s\", entry.q, entry.a)\
end\
\
function GameLines.thanks() return _(\"Thanks\") end\
\
--- The critter's comment on a quote, { mood, text }.\
function GameLines.comment(tier, rand)\
    local set = COMMENTS[tier] or COMMENTS.base\
    return { mood = TIER_MOOD[tier] or \"curious\", text = set[rand(#set)]() }\
end\
\
return GameLines\
",
    ["modules/critter/games"] = "-- games.lua — Simple UI\
-- Rules of the small games the Critter plays in the conversation: rock, paper,\
-- scissors, heads or tails and \"who said it?\", and the pick of the quotes it\
-- reads. Everything here is pure: `rand(n)` gives an integer from 1 to n\
-- (math.random) and the quotes are { q, a, b? } entries (modules/quotes.lua).\
\
local Games = {}\
\
Games.MOVES = { \"rock\", \"paper\", \"scissors\" }\
\
-- Longest quote that is read or asked about, in characters of what is shown (the\
-- quote, its author and the words around them): the window holds five lines.\
Games.MAX_QUOTE_LEN = 100\
Games.QUOTE_LINES   = 5\
\
-- Characters the quote and author are framed with: the marks, the dash and \"Who said\".\
local QUOTE_FRAME_LEN = 12\
\
-- Length of `text` in UTF-8 characters.\
local function charCount(text)\
    return select(2, text:gsub(\"[^\\128-\\191]\", \"\"))\
end\
\
-- What each move beats.\
local BEATS = { rock = \"scissors\", paper = \"rock\", scissors = \"paper\" }\
\
--- The critter's move against `move`, and how it went for the user: \"win\",\
--- \"lose\" or \"draw\".\
function Games.rps(move, rand)\
    local mine = Games.MOVES[rand(#Games.MOVES)]\
    if mine == move then return mine, \"draw\" end\
    return mine, BEATS[move] == mine and \"win\" or \"lose\"\
end\
\
--- The side the coin lands on (\"heads\" | \"tails\") and whether it is the `call`.\
function Games.coin(call, rand)\
    local side = rand(2) == 1 and \"heads\" or \"tails\"\
    return side, side == call\
end\
\
-- Positions of the quotes short enough to be read; every quote when none is.\
local function readable(quotes)\
    local list = {}\
    for i, entry in ipairs(quotes) do\
        local shown = charCount(entry.q) + (entry.a and charCount(entry.a) or 0) + QUOTE_FRAME_LEN\
        if shown <= Games.MAX_QUOTE_LEN then list[#list + 1] = i end\
    end\
    if #list == 0 then\
        for i = 1, #quotes do list[i] = i end\
    end\
    return list\
end\
\
--- A quote to read, and its position in `quotes`. The one at position `skip`\
--- is passed over unless it is the only choice.\
function Games.pickQuote(quotes, rand, skip)\
    local list = readable(quotes)\
    if #list > 1 then\
        for at, index in ipairs(list) do\
            if index == skip then table.remove(list, at); break end\
        end\
    end\
    local index = list[rand(#list)]\
    return quotes[index], index\
end\
\
-- Moves the entries of `list` around, in place.\
local function shuffle(list, rand)\
    for i = #list, 2, -1 do\
        local j = rand(i)\
        list[i], list[j] = list[j], list[i]\
    end\
    return list\
end\
\
--- A \"who said it?\" question about a quote that has an author: { quote, author,\
--- choices, answer }, where `choices` are three authors and `answer` the\
--- position of the right one. nil when `quotes` has fewer than three authors.\
function Games.quiz(quotes, rand)\
    local signed = {}\
    for _i, entry in ipairs(quotes) do\
        if entry.a then signed[#signed + 1] = entry end\
    end\
    if #signed == 0 then return nil end\
\
    local entry = Games.pickQuote(signed, rand)\
    local others, seen = {}, { [entry.a] = true }\
    for _i, other in ipairs(signed) do\
        if not seen[other.a] then\
            seen[other.a] = true\
            others[#others + 1] = other.a\
        end\
    end\
    if #others < 2 then return nil end\
\
    shuffle(others, rand)\
    local choices = shuffle({ entry.a, others[1], others[2] }, rand)\
    local answer\
    for i, author in ipairs(choices) do\
        if author == entry.a then answer = i end\
    end\
    return { quote = entry.q, author = entry.a, choices = choices, answer = answer }\
end\
\
return Games\
",
    ["modules/critter/menu"] = "-- menu.lua — Simple UI\
-- Settings > Tiny Critter: the settings of the critter that are the same on\
-- every screen (see settings.lua).\
\
local T           = require(\"ffi/util\").template\
local util        = require(\"util\")\
local Config      = require(\"infra/sui_config\")\
local Arrange     = require(\"features/sui_arrange\")\
local i18n        = require(\"infra/sui_i18n\")\
local _           = i18n.translate\
local N_          = i18n.ngettext\
local Assets      = require(\"modules/critter/assets\")\
local Phrases     = require(\"modules/critter/phrases\")\
local Settings    = require(\"modules/critter/settings\")\
\
local M = {}\
\
local MAX_NAME_CHARS = 20\
\
local function makeCritterItem(refresh, Settings)\
    local function get()\
        local entry = Assets.get(Settings.pick())\
        return entry and entry.id\
    end\
    return {\
        text_func  = function() return _(\"Critter\") end,\
        value_func = function()\
            local entry = Assets.get(Settings.pick())\
            return entry and entry.name or \"\"\
        end,\
        sub_item_table_func = function()\
            Assets.relist()\
            Assets.ensureUserDir()\
            local options = {}\
            for _i, entry in ipairs(Assets.list()) do\
                options[#options + 1] = { value = entry.id, label = entry.name }\
            end\
            local rows = Config.appendRadioItems({}, {\
                options = options,\
                get     = get,\
                set     = Settings.setPick,\
                refresh = refresh,\
            })\
            rows[#rows + 1] = {\
                text    = T(_(\"Add your own critters in %1\"), Assets.userDir()),\
                enabled = false,\
            }\
            return rows\
        end,\
    }\
end\
\
-- Menu row that asks for the name the critter uses for the user; an empty text\
-- clears it.\
local function makeNameItem(refresh)\
    return {\
        text_func      = function() return _(\"Your name\") end,\
        keep_menu_open = true,\
        value_func     = function() return Settings.userName() or _(\"Not set\") end,\
        callback       = function()\
            require(\"features/dialogs/sui_dialogs\").prompt{\
                title       = _(\"Your name\"),\
                description = _(\"The critter may use it in what it says.\"),\
                value       = Settings.userName() or \"\",\
                hint        = _(\"Name\"),\
                allow_empty = true,\
                validate    = function(text)\
                    if #util.splitToChars(text) > MAX_NAME_CHARS then\
                        return T(_(\"Use at most %1 characters.\"), tostring(MAX_NAME_CHARS))\
                    end\
                end,\
                on_submit   = function(text)\
                    Settings.setUserName(text)\
                    refresh()\
                end,\
            }\
        end,\
    }\
end\
\
-- Arrange row for the decorations of both sides, in one list: those of the left\
-- side, then those of the right, each as they stand on the screen. The arrange\
-- screen needs a menu context, which the native menu does not have.\
local function makeDecorItem(ctx_menu, refresh, Settings)\
    local arrange_ctx = setmetatable({ _ = _, refresh = refresh }, { __index = ctx_menu })\
    local title = _(\"Decorations\")\
    return Arrange.makeSectionedItem{\
        ctx_menu = arrange_ctx,\
        title    = title,\
        labels   = {\
            action  = string.format(_(\"Arrange %s\"), title),\
            empty   = _(\"No decorations selected.\"),\
            too_few = _(\"Add at least 2 decorations to arrange.\"),\
            full    = function(max)\
                return string.format(N_(\"The maximum of %d decoration per side has been reached. Remove one first.\",\
                    \"The maximum of %d decorations per side has been reached. Remove one first.\", max), max)\
            end,\
        },\
        sections = {\
            { id = \"left\",  label = _(\"Left\") },\
            { id = \"right\", label = _(\"Right\") },\
        },\
        max    = Settings.DECOR_PER_SIDE,\
        pool   = function()\
            local pool = {}\
            for _i, entry in ipairs(Assets.decorList()) do\
                pool[#pool + 1] = { id = entry.id, label = entry.name }\
            end\
            return pool\
        end,\
        getIds = Settings.decorIds,\
        setIds = Settings.setDecorIds,\
    }\
end\
\
local function makeStyleItem(refresh, Settings)\
    return Config.makeRadioSubmenuItem{\
        text    = _(\"Bubble style\"),\
        options = {\
            { value = \"pixel\",  label = _(\"Pixel\") },\
            { value = \"smooth\", label = _(\"Smooth\") },\
        },\
        get     = Settings.bubbleStyle,\
        set     = Settings.setBubbleStyle,\
        refresh = refresh,\
    }\
end\
\
local function makeSourceItem(refresh, Settings)\
    return Config.makeRadioSubmenuItem{\
        text    = _(\"Phrases\"),\
        options = {\
            { value = \"builtin\", label = _(\"Included\") },\
            { value = \"both\",    label = _(\"Included and mine\") },\
            { value = \"custom\",  label = _(\"Mine only\") },\
        },\
        get     = Settings.source,\
        set     = Settings.setSource,\
        refresh = refresh,\
    }\
end\
\
local function makeCategoriesItem(refresh, Settings)\
    return {\
        text_func = function() return _(\"Topics\") end,\
        sub_item_table_func = function()\
            local rows = {}\
            for _i, cat in ipairs(Phrases.CATEGORIES) do\
                rows[#rows + 1] = {\
                    text           = cat.label(),\
                    checked_func   = function() return Settings.categoryOn(cat.id) end,\
                    keep_menu_open = true,\
                    callback       = function()\
                        Settings.setCategory(cat.id, not Settings.categoryOn(cat.id))\
                        refresh()\
                    end,\
                }\
            end\
            return rows\
        end,\
    }\
end\
\
local function makeReactionsItem(refresh, Settings)\
    return {\
        text           = _(\"React to events\"),\
        checked_func   = Settings.reactionsOn,\
        keep_menu_open = true,\
        callback       = function()\
            Settings.setReactions(not Settings.reactionsOn())\
            refresh()\
        end,\
    }\
end\
\
-- Items of the menu. `rebuild`, when given, redraws the Home Screen; `ctx_menu`,\
-- when there is one, also redraws the window the menu is shown in.\
function M.getItems(ctx_menu, rebuild)\
    -- A module's menu keeps the scope of its saved pre-upgrade choices.\
    local scoped = Settings.forScreen(ctx_menu and ctx_menu.pfx)\
    local function refresh()\
        if rebuild then rebuild() end\
        if ctx_menu and ctx_menu.refresh then ctx_menu.refresh() end\
    end\
    -- Picks up the decorations the user added since the last time.\
    Assets.relist()\
    Assets.ensureUserDir()\
    return {\
        makeCritterItem(refresh, scoped),\
        makeDecorItem(ctx_menu, refresh, scoped),\
        {\
            text    = T(_(\"Add your own decorations in %1\"), Assets.userDecorDir()),\
            enabled = false,\
        },\
        makeStyleItem(refresh, scoped),\
        makeNameItem(refresh),\
        makeSourceItem(refresh, scoped),\
        makeCategoriesItem(refresh, scoped),\
        makeReactionsItem(refresh, scoped),\
    }\
end\
\
-- Entry that opens the menu above from the menu of a module or a panel.\
function M.makeSettingsItem(ctx_menu)\
    return {\
        text                = _(\"Tiny Critter Settings\"),\
        sub_item_table_func = function() return M.getItems(ctx_menu) end,\
    }\
end\
\
return M\
",
    ["modules/critter/panel_row"] = "-- panel_row.lua — Simple UI\
-- The Tiny Critter row of the Quick Settings panel: the module of the Home\
-- Screen, built for the width of the panel. The critter, its decorations, its\
-- bubble and what it says are the settings of Settings > Tiny Critter; only\
-- its position and scale are the panel's own, under the bar's prefix.\
-- The statistics are the ones already in memory for today: none is read here.\
\
local UIManager   = require(\"ui/uimanager\")\
local SUISettings = require(\"infra/sui_store\")\
local VirtualPaths = require(\"infra/sui_virtual_paths\")\
local _           = require(\"infra/sui_i18n\").translate\
\
local M = {}\
\
local PFX         = \"simpleui_qs_bar_\"\
local ENABLED_KEY = \"simpleui_qs_bar_critter_enabled\"\
\
function M.isEnabled() return SUISettings:isTrue(ENABLED_KEY) end\
function M.setEnabled(on) SUISettings:saveSetting(ENABLED_KEY, on) end\
\
-- Frees the row `touch_menu` shows, if any.\
function M.release(touch_menu)\
    local row = touch_menu._sui_qs_critter\
    if row then\
        touch_menu._sui_qs_critter = nil\
        row:free()\
    end\
end\
\
-- Closes the menu and opens the book `filepath`, from the reader or not.\
local function openBook(touch_menu, filepath)\
    local ReaderUI = package.loaded[\"apps/reader/readerui\"] or require(\"apps/reader/readerui\")\
    local reader = ReaderUI.instance\
    local generation = UIManager._simpleui_navigation_generation or 0\
    touch_menu:onClose()\
    UIManager:nextTick(function()\
        if ReaderUI.instance ~= reader or (reader and reader.tearing_down)\
                or generation ~= (UIManager._simpleui_navigation_generation or 0) then return end\
        local virtual = VirtualPaths.toVirtual(filepath)\
        if ReaderUI.instance then\
            ReaderUI.instance:switchDocument(virtual)\
        else\
            ReaderUI:showReader(virtual)\
        end\
    end)\
end\
\
-- Opens the settings of the row in a window: the row's own and, apart, the\
-- critter's. Closes the menu `touch_menu` first.\
local function openSettings(touch_menu)\
    local SUIWindow = require(\"engines/sui_window\")\
    local function buildRoot(ctx)\
        local ctx_menu = SUIWindow.makeCtxMenu(ctx)\
        return SUIWindow.MenuTable{\
            items      = M.getMenuItems(ctx_menu.refresh, ctx_menu),\
            inner_w    = ctx.inner_w,\
            repaint    = function() ctx.repaint() end,\
            push_stack = function(id, params)\
                if type(id) == \"string\" then ctx.push(id, params) else ctx.push(\"nested_menu\", params) end\
            end,\
            on_close   = function() end,\
        }\
    end\
    local win = SUIWindow:new{\
        name           = \"sui_win_context\",\
        title          = SUIWindow.makeSettingsTitle(_(\"Tiny Critter\")),\
        screens        = SUIWindow.makeSettingsScreens(buildRoot),\
        position       = \"bottom\",\
    }\
    touch_menu:onClose()\
    win:show()\
end\
\
-- The row for a panel `width` wide, nil when it is off. Registers its tap\
-- target in `refs.buttons` and its focus stop in `refs.focus_rows`.\
function M.build(touch_menu, refs, width)\
    M.release(touch_menu)\
    if not M.isEnabled() then return nil end\
\
    local Critter = require(\"modules/critter/module_critter\")\
    local stats = (package.loaded[\"modules/module_stats_provider\"]\
        or require(\"modules/module_stats_provider\")).getToday()\
    local cell\
    local row = Critter.build(width, {\
        pfx         = PFX,\
        stats       = stats or {},\
        stats_stale = stats == nil,\
        open_fn     = function(filepath) openBook(touch_menu, filepath) end,\
        on_hold     = function() openSettings(touch_menu) end,\
        kbStops     = function(_id, stops)\
            cell = stops[1] and stops[1].widget\
        end,\
    })\
    if cell then\
        table.insert(refs.buttons, {\
            widget   = cell,\
            callback = function() return cell:onTapCritter() end,\
        })\
        table.insert(refs.focus_rows, { cell })\
    end\
    touch_menu._sui_qs_critter = row\
    return row\
end\
\
-- Items of the bar's menu for the row: whether it shows, where the critter\
-- stands and how big it is, then the critter's own settings. `refresh` redraws\
-- the menu and the open panels; `outer_menu` is the context of the menu the\
-- items are shown in, if any.\
function M.getMenuItems(refresh, outer_menu)\
    local Critter  = require(\"modules/critter/module_critter\")\
    local ctx_menu = { pfx = PFX, _ = _, refresh = refresh }\
    local items = {\
        {\
            text           = _(\"Show Tiny Critter\"),\
            checked_func   = M.isEnabled,\
            keep_menu_open = true,\
            callback       = function()\
                M.setEnabled(not M.isEnabled())\
                refresh()\
            end,\
        },\
    }\
    for _i, item in ipairs(Critter.makePlacementItems(ctx_menu)) do items[#items + 1] = item end\
    items[#items + 1] = Critter.makeScaleItem(ctx_menu)\
    table.insert(items, 1, require(\"modules/critter/menu\").makeSettingsItem(outer_menu))\
    return items\
end\
\
return M\
",
    ["modules/critter/settings"] = "-- settings.lua — Simple UI\
-- Settings of the critter that are the same on every screen: which critter it\
-- is, the look of its bubble and how it behaves. What depends on where it is\
-- shown (side, alignment, scale, decorations, text) stays under the screen prefix.\
\
local Config      = require(\"infra/sui_config\")\
local SUISettings = require(\"infra/sui_store\")\
\
local M = {}\
\
M.STYLES         = { \"pixel\", \"smooth\" }\
M.DEFAULT_STYLE  = \"pixel\"\
M.SOURCES        = { \"builtin\", \"both\", \"custom\" }\
M.DEFAULT_SOURCE = \"both\"\
\
-- Decorations a side of the group holds at most, and what each side holds\
-- until the user arranges it.\
M.DECOR_PER_SIDE = 2\
local DEFAULT_DECOR = { left = { \"bookcase\", \"lamp\" }, right = {} }\
\
local KEY_PICK   = \"simpleui_critter_cfg_pick\"           -- id of the chosen critter\
local KEY_STYLE  = \"simpleui_critter_cfg_bubble_style\"   -- \"pixel\" | \"smooth\"\
local KEY_SOURCE = \"simpleui_critter_cfg_source\"         -- \"builtin\" | \"both\" | \"custom\"\
local KEY_REACT  = \"simpleui_critter_cfg_reactions\"      -- false = no reactions to events\
local KEY_CAT    = \"simpleui_critter_cfg_cat_\"           -- .. category id; false = category off\
local KEY_DECOR  = \"simpleui_critter_cfg_decor_\"         -- .. side; ids of the decorations of that side, left to right\
local KEY_NAME   = \"simpleui_critter_user_name\"          -- name the user told the critter\
\
-- Where the same settings lived before, under the prefix of the default screen.\
local LEGACY_PFX = \"simpleui_hs_\"\
local LEGACY = {\
    [KEY_PICK]   = \"critter_pick\",\
    [KEY_STYLE]  = \"critter_bubble_style\",\
    [KEY_SOURCE] = \"critter_source\",\
    [KEY_REACT]  = \"critter_reactions\",\
}\
local LEGACY_CAT = \"critter_cat_\"\
local LEGACY_DECOR = \"critter_decor_\"\
\
function M.pick() return SUISettings:get(KEY_PICK) end\
function M.setPick(id) SUISettings:set(KEY_PICK, id) end\
\
function M.bubbleStyle() return Config.readChoice(KEY_STYLE, M.STYLES, M.DEFAULT_STYLE) end\
function M.setBubbleStyle(v) SUISettings:set(KEY_STYLE, v) end\
\
function M.source() return Config.readChoice(KEY_SOURCE, M.SOURCES, M.DEFAULT_SOURCE) end\
function M.setSource(v) SUISettings:set(KEY_SOURCE, v) end\
\
function M.reactionsOn() return SUISettings:nilOrTrue(KEY_REACT) end\
function M.setReactions(on) SUISettings:set(KEY_REACT, on) end\
\
-- Ids of the decorations of `side`, left to right: the ones the user arranged,\
-- the default ones until then.\
function M.decorIds(side)\
    local ids = SUISettings:get(KEY_DECOR .. side)\
    return { unpack(type(ids) == \"table\" and ids or DEFAULT_DECOR[side]) }\
end\
function M.setDecorIds(side, ids) SUISettings:set(KEY_DECOR .. side, ids) end\
\
-- Name the user gave the critter, nil when there is none.\
function M.userName()\
    local name = SUISettings:get(KEY_NAME)\
    return type(name) == \"string\" and name ~= \"\" and name or nil\
end\
function M.setUserName(name) SUISettings:set(KEY_NAME, name ~= \"\" and name or nil) end\
\
function M.categoryOn(id) return SUISettings:nilOrTrue(KEY_CAT .. id) end\
function M.setCategory(id, on) SUISettings:set(KEY_CAT .. id, on) end\
\
-- OrbitUI: saved Home/custom-screen choices remain independent. New shared\
-- settings are defaults only; a module's own menu edits its original namespace.\
function M.forScreen(pfx)\
    if type(pfx) ~= \"string\" or pfx == \"\" then return M end\
    local function get(suffix, fallback)\
        local value = SUISettings:get(pfx .. suffix)\
        if value ~= nil then return value end\
        return fallback()\
    end\
    local function set(suffix, value) SUISettings:set(pfx .. suffix, value) end\
    local function choice(suffix, values, fallback)\
        local value = get(suffix, fallback)\
        for _, allowed in ipairs(values) do if value == allowed then return value end end\
        return fallback()\
    end\
    return setmetatable({\
        pick = function() return get(\"critter_pick\", M.pick) end,\
        setPick = function(v) set(\"critter_pick\", v) end,\
        bubbleStyle = function() return choice(\"critter_bubble_style\", M.STYLES, M.bubbleStyle) end,\
        setBubbleStyle = function(v) set(\"critter_bubble_style\", v) end,\
        source = function() return choice(\"critter_source\", M.SOURCES, M.source) end,\
        setSource = function(v) set(\"critter_source\", v) end,\
        reactionsOn = function() return get(\"critter_reactions\", M.reactionsOn) ~= false end,\
        setReactions = function(v) set(\"critter_reactions\", v) end,\
        categoryOn = function(id) return get(\"critter_cat_\" .. id, function() return M.categoryOn(id) end) ~= false end,\
        setCategory = function(id, v) set(\"critter_cat_\" .. id, v) end,\
        decorIds = function(side)\
            local ids = get(\"critter_decor_\" .. side, function() return M.decorIds(side) end)\
            return { unpack(type(ids) == \"table\" and ids or DEFAULT_DECOR[side]) }\
        end,\
        setDecorIds = function(side, ids) set(\"critter_decor_\" .. side, ids) end,\
    }, { __index = M })\
end\
\
-- Copies the values the default screen had into the global keys that are still\
-- unset. The other screens' values are left where they are.\
function M.migrateLegacy()\
    local function copy(new_key, legacy_key)\
        local value = SUISettings:get(LEGACY_PFX .. legacy_key)\
        if SUISettings:get(new_key) == nil and value ~= nil then\
            SUISettings:set(new_key, value)\
        end\
    end\
    for new_key, legacy_key in pairs(LEGACY) do copy(new_key, legacy_key) end\
    for _i, side in ipairs({ \"left\", \"right\" }) do\
        copy(KEY_DECOR .. side, LEGACY_DECOR .. side)\
    end\
    for _i, cat in ipairs(require(\"modules/critter/phrases\").CATEGORIES) do\
        copy(KEY_CAT .. cat.id, LEGACY_CAT .. cat.id)\
    end\
end\
\
return M\
",
    ["modules/critter/state"] = "-- state.lua — Simple UI\
-- Shallow copy and comparison of the plain state tables kept by mood.lua,\
-- reactions.lua and challenge.lua.\
\
local State = {}\
\
--- A copy of `state` with `changes` applied.\
function State.copy(state, changes)\
    local new = {}\
    for k, v in pairs(state) do new[k] = v end\
    for k, v in pairs(changes) do new[k] = v end\
    return new\
end\
\
--- Whether `a` and `b` hold the same values, ignoring the fields in `skip`.\
function State.same(a, b, skip)\
    for k, v in pairs(a) do\
        if not (skip and skip[k]) and b[k] ~= v then return false end\
    end\
    for k in pairs(b) do\
        if not (skip and skip[k]) and a[k] == nil then return false end\
    end\
    return true\
end\
\
return State\
",
    ["modules/critter/voice_lines"] = "-- voice_lines.lua — Simple UI\
-- Lines each bundled critter says in its own voice for the reactions of\
-- reaction_lines.lua; they are dealt along with the general lines.\
-- A line is { critter, kind, group, id, mood, text(data), sub?(data) }.\
\
local _ = require(\"infra/sui_i18n\").translate\
\
local Voices = {}\
\
-- Reaction of a situation and the groups of that reaction it fits.\
local BOOK          = { name = \"book\",      kind = \"book_finished\",  groups = { \"titled\" } }\
local SESSION       = { name = \"session\",   kind = \"session\",        groups = { \"long\" } }\
local SESSION_SHORT = { name = \"session\",   kind = \"session\",        groups = { \"short\", \"medium\" } }\
local COMEBACK      = { name = \"comeback\",  kind = \"comeback\",       groups = { \"week\" } }\
local COMEBACK_ANY  = { name = \"comeback\",  kind = \"comeback\",       groups = { \"few\", \"week\", \"month\" } }\
local BATTERY       = { name = \"battery\",   kind = \"battery_low\",    groups = { \"low\" } }\
local CHARGING      = { name = \"charging\",  kind = \"charging\",       groups = { \"charging\" } }\
local CHALLENGE     = { name = \"challenge\", kind = \"challenge_done\", groups = { \"done\" } }\
\
-- The `n`th line of `critter` for `situation`, once per group it fits.\
local function add(critter, situation, n, mood, text, sub)\
    for _i, group in ipairs(situation.groups) do\
        Voices[#Voices + 1] = {\
            critter = critter, kind = situation.kind, group = group,\
            id = string.format(\"v_%s_%s_%d_%s\", critter, situation.name, n, group),\
            mood = mood, text = text, sub = sub,\
        }\
    end\
end\
\
-- Suey.\
\
add(\"suey\", BOOK, 1, \"happy\",\
    function(d) return string.format(_(\"%s, finished? Acceptable.\"), d.title) end,\
    function() return _(\"I'll allow a purr.\") end)\
add(\"suey\", SESSION, 1, \"sleepy\",\
    function() return _(\"Long session. I napped twice.\") end,\
    function() return _(\"On your book, mostly.\") end)\
add(\"suey\", COMEBACK_ANY, 1, \"shy\",\
    function() return _(\"Oh. You're back.\") end,\
    function() return _(\"I wasn't waiting. Much.\") end)\
add(\"suey\", BATTERY, 1, \"surprised\",\
    function() return _(\"Low battery. Do something.\") end,\
    function() return _(\"Or I'll knock it off the shelf.\") end)\
add(\"suey\", CHARGING, 1, \"sleepy\",\
    function() return _(\"Warm cable. Mine now.\") end,\
    function() return _(\"Do not disturb.\") end)\
add(\"suey\", CHALLENGE, 1, \"love\",\
