\
-- Chonk.\
\
add(\"chonk\", BOOK, 1, \"surprised\",\
    function(d) return string.format(_(\"%s is over. Mongo is appalled.\"), d.title) end,\
    function() return _(\"He wanted a sequel.\") end)\
add(\"chonk\", SESSION, 1, \"cheer\",\
